insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا نِسَاءَ الْمُسْلِمَاتِ، لَا تَحْقِرَنَّ جَارَةٌ لِجَارَتِهَا، وَلَوْ فِرْسِنَ شَاةٍ". (خ)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലയോ മുസ്ലിം സ്ത്രീകളേ, ഒരയൽവാസിനി വല്ലതും ദാനമായി നൽകുമ്പോൾ അതിനെ നിസാരമാക്കരുത്. അതൊരു ആട്ടിൻ പാദമാണെങ്കിലും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "تَهَادَوْا، فَإِنَّ الْهَدِيَّةَ تُذْهِبُ وَحَرَ الصَّدْرِ، وَلَا تَحْقِرَنَّ جَارَةٌ لِجَارَتِهَا وَلَوْ شقَّ فِرْسِنِ شَاةٍ". (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പരസ്പരം പാരിതോഷികം നൽകുക. കാരണം, പാരിതോഷികം ഹൃദയത്തിലെ ദേഷ്യത്തെ നീക്കിക്കളയും. ഒരു അയൽവാസിനിയും മറ്റൊരു അയൽവാസിനിയുടെ കാര്യത്തെ നിസാരമാക്കരുത്. അതൊരു ആടിൻപാദത്തിന്റെ കഷ്ണം കൊടുക്കുമ്പോഴാണെങ്കിലും." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا قَالَتْ لِعُرْوَةَ: يَا ابْنَ أُخْتِي، إِنْ كُنَّا لَنَنْظُرُ إِلَى الْهِلَالِ ثُمَّ الْهِلَالِ ثَلَاثَةَ أَهِلَّةٍ فِي شَهْرَيْنِ، وَمَا أُوقِدَتْ فِي أَبْيَاتِ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَارٌ. فَقُلْتُ: يَا خَالَةُ، مَا كَانَ يُعِيشُكُمْ؟ قَالَتْ: الْأَسْوَدَانِ، التَّمْرُ وَالْمَاءُ، إِلَّا أَنَّهُ قَدْ كَانَ لِرَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جِيرَانٌ مِنَ الْأَنْصَارِ، كَانَتْ لَهُمْ مَنَائِحُ، وَكَانُوا يَمْنَحُونَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَلْبَانِهِمْ، فَيَسْقِينَا. (ق,د,ت,ن,جه)', 'ആഇശ(റ): അവർ ഉർവ(റ)വിനോട് പറഞ്ഞു: എന്റെ സഹോദരീ പുത്രാ, ഞങ്ങൾ ഒരു ചന്ദ്രപ്പിറവി കാണും, വീണ്ടും ചന്ദ്രപ്പിറവി കാണും. അങ്ങനെ രണ്ടു മാസങ്ങളിലായി മുന്ന് ചന്ദ്രപ്പിറവി കാണും. ഈ സമയത്തൊന്നും തന്നെ റസൂൽ(സ)യുടെ വീടുകളിൽ തീ കത്തിക്കപ്പെട്ടിട്ടുണ്ടായിരിക്കില്ല. ഞാൻ (ഉർവ) ചോദിച്ചു. എന്റെ മാതൃസഹോദരീ, അന്നൊക്കെ നിങ്ങളുടെ ജീവതാവലംബം എന്തായിരുന്നു? ആഇശ(റ) പറഞ്ഞു: രണ്ടു കറുത്ത സാധനങ്ങൾ, അഥവാ കാരക്കയും വെള്ളവുമായിരുന്നു (ഞങ്ങളുടെ ആശ്രയം). പക്ഷേ, നബി(സ)ക്ക് അൻസ്വാറുകളിൽപെട്ട ചില അയൽവാസികളും അവർക്ക് കുറച്ച് കാലികളുമുണ്ടായിരുന്നു. അവയുടെ പാൽ അവർ നബി(സ)ക്ക് സമ്മാനിക്കുമ്പോൾ അവിടുന്ന് ഞങ്ങളേയും കുടിപ്പിക്കുമായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَوْ دُعِيتُ إِلَى ذِرَاعٍ أَوْ كُرَاعٍ لَأَجَبْتُ، وَلَوْ أُهْدِيَ إِلَيَّ ذِرَاعٌ أَوْ كُرَاعٌ لَقَبِلْتُ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മൃഗത്തിന്റെ കയ്യോ കാലോ തിന്നാൻ എന്നെ ക്ഷണിച്ചാൽ ഞാൻ സ്വീകരിക്കും. ഒരു കയ്യോ കലോ പാരിതോഷികമായി നൽകപ്പെട്ടാൽ ഞാൻ സ്വീകരിക്കും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 859, 859, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَنْفَجْنَا أَرْنَبًا بِمَرِّ الظَّهْرَانِ، فَسَعَى الْقَوْمُ فَلَغِبُوا، فَأَدْرَكْتُهَا فَأَخَذْتُهَا، فَأَتَيْتُ بِهَا أَبَا طَلْحَةَ، فَذَبَحَهَا وَبَعَثَ بِهَا إِلَى رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَرِكِهَا، أَوْ فَخِذَيْهَا، فَقَبِلَهُ. وَفِي رِوَايَةٍ: وَأَكَلَ مِنْهُ. (خ)', 'അനസ്(റ): ‘മർറുള്ളഹ്റാനി’ൽ വെച്ച് ഞങ്ങൾ ഒരു മുയലിനെ ഓടിച്ചു. അങ്ങനെ ജനങ്ങൾ ഓടി ക്ഷീണിച്ചു. എന്നാൽ ഞാനതിനെ കണ്ടെത്തി പിടികൂടി. അതുമായി ഞൻ അബൂത്വൽഹ(റ)വിന്റെ അടുത്തു ചെന്നു. അദ്ദേഹം അതിനെ അറുത്തു. അതിന്റെ ഊരയോ രണ്ട് തുടകളോ നബി(സ)ക്ക് കൊടുത്തയച്ചു. അപ്പോൾ നബി(സ) അത് സ്വീകരിച്ചു. മറ്റൊരു റിപ്പോർട്ടിലുണ്ട്: നബി(സ) അതിൽ നിന്ന് ഭക്ഷിച്ചു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=5), 1, 'وَفِي رِوَايَةٍ: وَأَكَلَ مِنْهُ. (خ)', 'മറ്റൊരു നിവേദനിലുണ്ട്: നബി(സ) അതിൽ നിന്ന് ഭക്ഷിച്ചു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَهْدَتْ أُمُّ حُفَيْدٍ خَالَةُ ابْنِ عَبَّاسٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقِطًا وَسَمْنًا وَأَضُبًّا، فَأَكَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْأَقِطِ وَالسَّمْنِ، وَتَرَكَ الْأَضُبَّ تَقَذُّرًا، قَالَ ابْنُ عَبَّاسٍ: فَأُكِلَ عَلَى مَائِدَة رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَوْ كَانَ حَرَامًا مَا أُكِلَ عَلَى مَائِدَة رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ഇബ്നുഅബ്ബസ്(റ): ഇബ്നുഅബ്ബാസ്(റ)വിന്റെ മാതൃസഹോദരി ഉമ്മുഹുഫൈദ്(റ) നബി(സ)ക്ക് പാൽകട്ടിയും നെയ്യും ഉടുമ്പും സമ്മാനമായി നൽകി. നബി(സ) നെയ്യും പൽകട്ടിയും ഭക്ഷിച്ചു. വെറുപ്പോടെ ഉടുമ്പിനെ മാറ്റിവെച്ചു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു. അതിനെ നബി(സ)യുടെ സുപ്രയിൽ വെച്ച് ഭക്ഷിക്കപ്പെട്ടു. അത് നിഷിദ്ധമായിരുന്നുവെങ്കിൽ റസൂൽ(സ)യുടെ സുപ്രയിൽ വെച്ച് അത് ഭക്ഷിക്കപ്പെടുമായിരുന്നില്ല. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أُتِيَ بِطَعَامٍ سَأَلَ عَنْهُ: "أَهَدِيَّةٌ أَمْ صَدَقَةٌ؟" فَإِنْ قِيلَ: صَدَقَةٌ، قَالَ لِأَصْحَابِهِ: "كُلُوا". وَلَمْ يَأْكُلْ، وَإِنْ قِيلَ: هَدِيَّةٌ، ضَرَبَ بِيَدِهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَكَلَ مَعَهُمْ. (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ)യുടെ അടുക്കൽ വല്ല ഭക്ഷണവും കൊണ്ടുവരപ്പെട്ടാൽ അവിടുന്ന് ചോദിക്കും: ഇത് ദാനമാണോ അതോ പാരിതോഷികമാണോ? ദാനമാണെന്ന് പറയപ്പെട്ടാൽ അവിടുന്ന് അനുചരരോട് പറയും: "നിങ്ങൾ ഭക്ഷിച്ചു കൊള്ളുക." തിരുമേനി(സ) അതിൽനിന്ന് ഭക്ഷിക്കുകയുമില്ല. പാരിതോഷികമാണെന്ന് പറയെപ്പെട്ടാൽ അവിടുന്ന് തന്റെ കൈകൊണ്ട് അടിക്കുകയും അവരോടൊപ്പം ഭക്ഷിക്കുകയും ചെയ്യും. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 860, 860, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ نِسَاءَ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُنَّ حِزْبَيْنِ، فَحِزْبٌ فيه عَائِشَةُ وَحَفْصَةُ وَصَفِيَّةُ وَسَوْدَةُ، وَالْحِزْبُ الْآخَرُ فيه أُمُّ سَلَمَةَ وَسَائِرُ نسَاء رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ الْمُسْلِمُونَ قَدْ عَلِمُوا حُبَّ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَائِشَةَ، فَإِذَا كَانَتْ عِنْدَ أَحَدِهِمْ هَدِيَّةٌ يُرِيدُ أَنْ يُهْدِيَهَا إِلَى رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَّرَهَا، حَتَّى إِذَا كَانَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ عَائِشَةَ بَعَثَ صَاحِبُ الْهَدِيَّةِ بِهَا إِلَى رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِ عَائِشَةَ، فَكَلَّمَ حِزْبُ أُمِّ سَلَمَةَ، فَقُلْنَ لَهَا: كَلِّمِي رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكَلِّمُ النَّاسَ، فَيَقُولُ: مَنْ أَرَادَ أَنْ يُهْدِيَ إِلَى رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَدِيَّةً فَلْيُهْدِهِ إِلَيْهِ حَيْثُ كَانَ مِنْ بُيُوتِ نِسَائِهِ. فَكَلَّمَتْهُ أُمُّ سَلَمَةَ بِمَا قُلْنَ لَهَا، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا، فَقَالَتْ: مَا قَالَ لِي شَيْئًا، فَقُلْنَ لَهَا: فَكَلِّمِيهِ، قَالَتْ: فَكَلَّمَتْهُ حِينَ دَارَ إِلَيْهَا أَيْضًا، فَلَمْ يَقُلْ لَهَا شَيْئًا، فَسَأَلْنَهَا، فَقَالَتْ: مَا قَالَ لِي شَيْئًا، فَقُلْنَ لَهَا: كَلِّمِيهِ حَتَّى يُكَلِّمَكِ، فَدَارَ إِلَيْهَا، فَكَلَّمَتْهُ. فَقَالَ لَهَا: "لَا تُؤْذِينِي فِي عَائِشَةَ، فَإِنَّ الْوَحْيَ لَمْ يَأْتِنِي وَأَنَا فِي ثَوْبِ امْرَأَة، إِلَّا عَائِشَةَ". قَالَتْ: فَقُلْتُ: أَتُوبُ إِلَى اللَّهِ مِنْ أَذَاكَ يَا رَسُول اللَّه، ثُمَّ إِنَّهُنَّ دَعَوْنَ فَاطِمَةَ بِنْتَ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَرْسَلَتْ إِلَى رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَقُولُ: إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ أَبِي بَكْرٍ، فَكَلَّمَتْهُ، فَقَالَ: "يَا بُنَيَّةُ، أَلَا تُحِبِّينَ مَا أُحِبُّ". قَالَتْ: بَلَى. فَرَجَعَتْ إِلَيْهِنَّ، فَأَخْبَرَتْهُنَّ، فَقُلْنَ: ارْجِعِي إِلَيْهِ، فَأَبَتْ أَنْ تَرْجِعَ. فَأَرْسَلْنَ زَيْنَبَ بِنْتَ جَحْشٍ، فَأَتَتْهُ فَأَغْلَظَتْ وَقَالَتْ: إِنَّ نِسَاءَكَ يَنْشُدْنَكَ اللَّهَ الْعَدْلَ فِي بِنْتِ ابْنِ أَبِي قُحَافَةَ، فَرَفَعَتْ صَوْتَهَا، حَتَّى تَنَاوَلَتْ عَائِشَةَ وَهِيَ قَاعِدَةٌ، فَسَبَّتْهَا، حَتَّى إِنَّ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَنْظُرُ إِلَى عَائِشَةَ هَلْ تَكَلَّمُ، قَالَ: فَتَكَلَّمَتْ عَائِشَةُ تَرُدُّ عَلَى زَيْنَبَ، حَتَّى أَسْكَتَتْهَا، قَالَتْ: فَنَظَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عَائِشَةَ، وَقَالَ: "إِنَّهَا بِنْتُ أَبِي بَكْرٍ". (خ)', 'ആഇശ(റ): തിരുമേനി(സ)യുടെ ഭാര്യമാർ രണ്ടു വിഭാഗമായിരുന്നു. ആഇശ(റ), ഹഫ്സ്വ(റ), സ്വഫിയ്യ(റ), സൗദ(റ) എന്നിവരുടെ ഒരു വിഭാഗവും, ഉമ്മുസലമ(റ)യും പ്രവാചകർ(സ)യുടെ മറ്റുള്ള ഭാര്യമാരും അടങ്ങുന്ന മറ്റൊരു വിഭാഗവും. ആഇശ(റ)യോട് പ്രവാചകർ(സ)ക്കുള്ള സ്നേഹത്തെക്കുറിച്ച് മുസ്ലിംകൾക്കൊല്ലാം അറിയാമായിരുന്നു. അവരുടെ പക്കൽ നബി(സ)ക്കുള്ള വല്ല പാരിതോഷികവും ഉണ്ടെങ്കിൽ അതിനെ അവർ പിന്തിപ്പിച്ചു വെക്കുകയും അങ്ങനെ പ്രവാചകർ(സ) എന്റെ വീട്ടിലാകുന്ന സമയത്ത് പാരിതോഷികം അവർ റസൂൽ(സ)ക്ക് കൊടുത്തയക്കുകയും ചെയ്യും. (ഇതിനെ സംബന്ധിച്ച്) ഉമ്മുസലമ(റ)യുടെ വിഭാഗം കൂടിയാലോചന നടത്തി. അവർ ഉമ്മുസലമ(റ)യോട് പറഞ്ഞു: വല്ലവരും പ്രവാചകർ(സ)ക്ക് വല്ല പാരിതോഷികവും നൽകാൻ ഉദ്ദേശിക്കുകയാണെങ്കിൽ, അവിടുന്ന് ഏത് ഭാര്യയുടെ വീട്ടിലാണെങ്കിലും അവിടുത്തേക്ക് സമ്മാനിക്കണമെന്ന് ജനങ്ങൾക്ക് നിർദ്ദേശം നൽകാൻ തിരുനബി(സ)യോട് നീ ആവശ്യപ്പെടണം. അവരുടെ നിർദ്ദേശപ്രകാരം ഉമ്മുസലമ(റ) നബി(സ)യോട് സംസാരിച്ചു. പക്ഷേ, അവിടുന്ന് ഒന്നും പ്രതികരിച്ചില്ല. അങ്ങനെ അവർ ഉമ്മുസലമ(റ)യോട് ചോദിച്ചപ്പോൾ മഹതി പറഞ്ഞു: അവിടുന്ന് എന്നോടൊന്നും പ്രതികരിച്ചിട്ടില്ല. അവർ പറഞ്ഞു: എങ്കിൽ നീ വീണ്ടും സംസാരിക്കുക. മഹതി പറയുന്നു: അങ്ങനെ ഉമ്മുസലമ(റ)യുടെ ഊഴദിവസം എത്തിയപ്പോൾ അവർ വീണ്ടും അതിനെക്കുറിച്ച് സംസാരിച്ചെങ്കിലും അവിടുന്ന് ഒന്നും പ്രതികരിച്ചില്ല. അങ്ങനെ അവർ ഉമ്മുസലമ(റ)യോട് ചോദിച്ചപ്പോൾ മഹതി പറഞ്ഞു: അവിടുന്ന് എന്നോടൊന്നും പ്രതികരിച്ചിട്ടില്ല. അവർ പറഞ്ഞു: എങ്കിൽ നിന്നോട് തിരുമേനി(സ) പ്രതികരിക്കുവോളം നീ അവിടുത്തോട് സംസാരിക്കുക. അങ്ങനെ അവരുടെ ഊഴദിവസം അവർ നബി(സ)യോട് വീണ്ടും സംസാരിച്ചു. ആ സമയത്ത് നബി(സ) ഉമ്മുസലമ(റ)യോട് പറഞ്ഞു: "ആഇശയുടെ കാര്യത്തിൽ എന്നെ നീ പ്രയാസപ്പെടുത്തരുത്. ആഇശയല്ലാത്ത മറ്റൊരു ഭാര്യയുടെ വസ്ത്രത്തിൽ കഴിയുമ്പോഴും എനിക്ക് ദിവ്യബോധനം (വഹ്യ്) വന്നിട്ടില്ല." ഉമ്മുസലമ(റ) പറയുന്നു: തൽസമയം ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുത്തെ ബുദ്ധിമുട്ടിച്ചതിൽ നിന്നും അല്ലാഹുവിലേക്ക് ഞാൻ പശ്ചാതപിച്ചു മടങ്ങുന്നു. ഉമ്മുസലമ(റ)യുടെ വിഭാഗം പിന്നീട് പ്രവാചക പുത്രി ഫാതിമ(റ)യെ വിളിക്കുകയും മഹതിയെ പ്രവാചകർ(സ)യുടെ അടുത്തേക്ക് ഇപ്രകാരം പറഞ്ഞയക്കുകയും ചെയ്തു: അങ്ങയുടെ പത്നിമാർ അല്ലാഹുവിനെ മുൻനിർത്തി അബൂബക്കറിന്റെ പുത്രിയുടെ കാര്യത്തിൽ നീതി പുലർത്തണമെന്നാവശ്യപ്പെടുന്നു. അങ്ങനെ മഹതി തിരുമേനി(സ)യോട് സംസാരിച്ചു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "എന്റെ പ്രിയ മകളേ, ഞാൻ ഇഷ്ടപ്പെടുന്നതിനെ നിനക്കും ഇഷ്ടമല്ലേ?" മഹതി പറഞ്ഞു: അതെ. അങ്ങനെ മഹതി പ്രവാചക പത്നിമാരുടെ അടുത്തേക്ക് തിരിച്ചുപോയി കാര്യങ്ങൾ വിശദീകരിച്ചു. അപ്പോൾ അവർ പറഞ്ഞു: നീ വീണ്ടും തുരുമേനി(സ)യിലേക്ക് തിരിച്ചുപോവുക. എന്നാൽ ഫാതിമ(റ) വിസമ്മതിച്ചു. പിന്നീടവർ പ്രതിനിധിയായി അയച്ചത് സൈനബ് ബിൻതുജഹ്ശ്(റ)യെയാണ്. മഹതി ചെന്ന്, അങ്ങയുടെ പത്നിമാർ അല്ലാഹുവിനെ മുൻനിർത്തിക്കൊണ്ട് അബൂഖുഹാഫയുടെ മകന്റെ മകളുടെ കാര്യത്തിൽ നീതി പാലിക്കണമെന്ന് അപേക്ഷിക്കുന്നുവെന്ന് കുറച്ച് ഉച്ചത്തിലും പരുഷ ഭാവത്തിലും പറഞ്ഞു. അവിടെ ഇരിക്കുകയായിരുന്ന ആഇശ(റ)യെ മഹതി ആക്ഷേപിക്കുക കൂടി ചെയ്തു. ആ സമയമെല്ലാം തരുമേനി(സ) ആഇശ(റ)യെ, മഹതി വല്ലതും പറയുന്നുണ്ടോ എന്ന് വീക്ഷിച്ചു കൊണ്ടിരിക്കുകയായിരുന്നു. നിവേദകൻ പറയുന്നു: ഉടൻതന്നെ ആഇശ(റ) സൈനബ്(റ)ക്ക് മറുപടി നൽകുകയും മഹതിയെ തോൽപിക്കുകയും ചെയ്തു. ആഇശ(റ) പറയുന്നു: അപ്പോൾ, നബി(സ) ആഇശ(റ)യിലേക്ക് നോക്കിക്കൊണ്ട് പറഞ്ഞു: "അവൾ അബൂബകറിന്റെ പുത്രിയാണ്." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 860, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَرُدُّ الطِّيبَ. (خ)', 'അനസ്(റ): നിശ്ചയം നബി(സ) സുഗന്ധം നിരസിക്കാറുണ്ടായിരുന്നില്ല. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ مَيْمُونَةَ بِنْت الْحَارِث رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا أَعْتَقَتْ وَلِيدَةً، وَلَمْ تَسْتَأْذن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا كَانَ يَوْمُهَا الَّذِي يَدُورُ عَلَيْهَا فِيه، قَالَتْ: أَشَعَرْتَ يَا رَسُولَ اللَّه، أَنِّي أَعْتَقْتُ وَلِيدَتِي؟ قَالَ: "أَوَفَعَلْتِ؟" قَالَتْ: نَعَمْ، قَالَ: "أَمَا إِنَّك لَوْ أَعْطَيْتِهَا أَخْوَالك، كَانَ أَعْظَمَ لِأَجْرك". (خ)', 'മൈമൂന ബിൻതുൽഹാരിസ്(റ): നബി(സ)യോട് സമ്മതം ചോദിക്കാതെ മഹതി തന്റെ ഒരു അടിമസ്ത്രീയെ മോചിപ്പിച്ചു. പ്രവാചകർ(സ)യിൽ നിന്നും അവരുടെ ഊഴ ദിനമായപ്പോൾ അവർ പ്രവാചകർ(സ)യോട് ചോദിച്ചു: തിരുദൂതരേ, ഞാൻ എന്റെ അടിമസ്ത്രീയെ മോചിപ്പിച്ച വിവരം അവിടുന്ന് അറിഞ്ഞോ? റസൂൽ(സ) ചോദിച്ചു: നീയതു ചെയ്തോ? മഹതി പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "അവളെ നിന്റെ അമ്മാവന്മാർക്ക് നീ നൽകിയിരുന്നുവെങ്കിൽ അതാകുമായിരുന്നു നിനക്ക് പ്രതിഫലത്തിൽ കൂടുതൽ മഹത്തരമായത്." (ബു)', 'مَيْمُونَةَ بِنْت الْحَارِث', 'മൈമൂന ബിൻതുൽഹാരിസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَرَادَ سَفَرًا أَقْرَعَ بَيْنَ نِسَائِه، فَأَيَّتُهُنَّ خَرَجَ سَهْمُهَا خَرَجَ بِهَا مَعَهُ، وَكَانَ يَقْسِمُ لِكُلِّ امْرَأَةٍ مِنْهُنَّ يَوْمَهَا وَلَيْلَتَهَا، غَيْرَ أَنَّ سَوْدَةَ بِنْتَ زَمْعَةَ وَهَبَتْ يَوْمَهَا وَلَيْلَتَهَا لِعَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، تَبْتَغِي بِذَلِكَ رِضَا رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ആഇശ(റ): തിരുദൂതർ(സ) ഒരു യാത്ര ഉദ്ദേശിക്കുന്ന അവസരത്തിൽ തന്റെ ഭാര്യമാർക്കിടയിൽ നറുക്കിടുമായിരുന്നു. അവരിൽ ആരുടെ നറുക്കാണ് വീണതെങ്കിൽ അവരുമായി പ്രവാചകർ(സ) പുറപ്പെടും. ഭാര്യമാരിൽ നിന്നും ഒരോരുത്തർക്കും അവരവരുടെ ദിനരാത്രങ്ങൾ അവിടുന്ന് ഓഹരി ചെയ്യാറുണ്ടായിരുന്നു. എന്നാൽ സൗദബിൻതു സംഅ(റ) തിരുദൂതർ(സ)യുടെ തൃപ്തി കാംക്ഷിച്ച് തന്റെ ദിനരാത്രങ്ങൾ പ്രവാചക പത്നി ആഇശ(റ)ക്ക് നൽകിയിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ: قَسَمَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْبِيَةً، وَلَمْ يُعْطِ مَخْرَمَةَ مِنْهَا شَيْئًا. فَقَالَ مَخْرَمَةُ: يَا بُنَيَّ، انْطَلِقْ بِنَا إِلَى رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَانْطَلَقْتُ مَعَهُ، فَقَالَ: ادْخُلْ فَادْعُهُ لِي، قَالَ: فَدَعَوْتُهُ لَهُ، فَخَرَجَ إِلَيْه وَعَلَيْه قَبَاءٌ مِنْهَا، فَقَالَ: "خَبَأْنَا هَذَا لَكَ". قَالَ: فَنَظَرَ إِلَيْه، فَقَالَ: "رَضِيَ مَخْرَمَةُ". (خ)', 'മിസ്വറുബ്നു മഖ്റമ(റ): തിരുദൂതർ(സ) കുറച്ച് കരിമ്പടങ്ങൾ വിതരണം ചെയ്തു. അതിൽ നിന്നും (എന്റെ പിതാവ്) മഖ്റമക്ക് ഒന്നും നൽകിയില്ല. അദ്ദേഹം പറഞ്ഞു: മകനേ, നമ്മെയും കൂട്ടി നീ റസൂൽ(സ)യുടെ അടുത്ത് പോവുക. അങ്ങനെ ഞാൻ അദ്ദേഹത്തിന്റെ കൂടെ പോയി. അദ്ദേഹം എന്നോട് പറഞ്ഞു: അകത്തു കടന്ന് എനിക്കുവേണ്ടി തിരുമേനി(സ)യെ വിളിക്കൂ. അങ്ങനെ ഞാൻ തിരുമേനി(സ)യെ അദ്ദേഹത്തിനായി വിളിച്ചു. അപ്പോൾ അതിൽപെട്ട ഒരു കരിമ്പുടവുമായി അവിടുന്ന് പുറത്തു വന്നു, എന്നിട്ട് പറഞ്ഞു: "ഇത് നിനക്കുവേണ്ടി നാം മാറ്റിവെച്ചതായിരുന്നു." നിവേദകൻ പറയുന്നു: അപ്പോൾ മഖ്റമ(റ) അതിലേക്ക് നോക്കി. ഉടനെ റസൂൽ(സ) പറഞ്ഞു: "മഖ്റമ സംതൃപ്തനായല്ലോ?" (ബു)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്വറുബ്നു മഖ്റമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 862, 862, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَتَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْتَ فَاطِمَةَ بِنْتِه رَضِيَ اللَّهُ عَنْهَا، فَلَمْ يَدْخُلْ عَلَيْهَا، وَجَاءَ عَلِيٌّ فَذَكَرَتْ لَهُ ذَلِكَ، فَذَكَرَهُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "إِنِّي رَأَيْتُ عَلَى بَابِهَا سِتْرًا مَوْشِيًّا، فَقَالَ: مَا لِي وَلِلدُّنْيَا". فَأَتَاهَا عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ، فَذَكَرَ ذَلِكَ لَهَا، فَقَالَتْ: لِيَأْمُرْنِي فِيه بِمَا شَاء، قَالَ: "تُرْسِلِي بِه إِلَى فُلَان أَهْل بَيْت بِهِمْ حَاجَةٌ". (خ)', 'ഇബ്നുഉമർ(റ): തിരുനബി(സ) തന്റെ മകൾ ഫാത്തിമ(റ)യുടെ വീട്ടിൽ ചെന്നു. പക്ഷേ, ഫാത്തിമ(റ)യുടെ അടുത്തേക്ക് പ്രവേശിച്ചില്ല. ശേഷം അലി(റ) വന്നപ്പോൾ മഹതി വിഷയം അദ്ദേഹത്തോട് അവതരിപ്പിക്കുകയും അദ്ദേഹം അത് നബി(സ)യോട് പറയുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "ഞാനവളുടെ വാതിൽക്കൽ ചിത്രപ്പണികളുള്ള ഒരു വിരി കണ്ടു. ഐഹിക ആഡംബരങ്ങളുമായി എനിക്കെന്ത് ബന്ധം?" അങ്ങനെ അലി(റ) ഫാത്വിമ(റ)യുടെ അടുത്ത് ചെന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ മഹതി പറഞ്ഞു: തിരുമേനി(സ) അക്കാര്യത്തിൽ എന്നോട് എന്തു വേണമെങ്കിലും കൽപിച്ചുക്കൊള്ളട്ടെ. നബി(സ) പറഞ്ഞു: "അത് ആവശ്യമുള്ള ഇന്നാലിന്നയാളുടെ വീട്ടിലേക്ക് നീ കൊടുത്തയക്കുക." (ബു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَهْدَى إِلَيَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُلَّةَ سِيَرَاءَ فَلَبِسْتُهَا، فَرَأَيْتُ الْغَضَبَ فِي وَجْهِهِ، فَشَقَقْتُهَا بَيْنَ نِسَائِي. (خ)', 'അലി(റ): നബി(സ) എനിക്ക് പട്ടുകൊണ്ട് നെയ്ത ഒരു വസ്ത്രം സമ്മാനിച്ചു. ഞാനത് ധരിച്ചപ്പോൾ അവിടുത്തെ മുഖത്ത് ഞാൻ കോപം ദർശിച്ചു. ഉടനെ ഞാനത് എന്റെ (കുടുംബത്തിലെ) സ്ത്രീകൾക്ക് മുറിച്ച് കൊടുത്തു. (ബു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ عَبْدالرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثِينَ وَمَائَةً، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ مَعَ أَحَد مِنْكُمْ طَعَامٌ؟" فَإِذَا مَعَ رَجُلٍ صَاعٌ مِنْ طَعَامٍ، أَوْ نَحْوُهُ، فَعُجِنَ، ثُمَّ جَاءَ رَجُلٌ مُشْرِكٌ مُشْعَانٌّ طَوِيلٌ، بِغَنَمٍ يَسُوقُهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَيْعًا أَمْ عَطِيَّةً، أَوْ قَالَ: أَمْ هِبَةً". قَالَ: لَا، بَلْ بَيْعٌ. فَاشْتَرَى مِنْهُ شَاةً، فَصُنِعَتْ، وَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَوَادِ الْبَطْنِ أَنْ يُشْوَى، وَايْمُ اللَّهِ مَا فِي الثَّلَاثِينَ وَالْمَائَةِ إِلَّا قَدْ حَزَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُ حُزَّةً مِنْ سَوَادِ بَطْنِهَا، إِنْ كَانَ شَاهِدًا أَعْطَاهَا إِيَّاهُ، وَإِنْ كَانَ غَائِبًا خَبَأَ لَهُ، فَجَعَلَ مِنْهَا قَصْعَتَيْنِ، فَأَكَلُوا أَجْمَعُونَ، وَشَبِعْنَا، فَفَضَلَتِ الْقَصْعَتَانِ فَحَمَلْنَاهُ عَلَى الْبَعِيرِ، أَوْ كَمَا قَالَ. (خ)', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ): ഒരിക്കൽ നബി(സ)യുടെ കൂടെ ഞങ്ങൾ നൂറ്റി മുപ്പത് പേരുണ്ടായിരുന്നു. "നിങ്ങളുടെ ആരുടെയെങ്കിലും പക്കൽ വല്ല ഭക്ഷണവുമുണ്ടോ" എന്ന് അവിടുന്ന് അന്വേഷിച്ചു. ഒരാളുടെ കയ്യിൽ ഏകദേശം ഒരു സ്വാഅ് ഭക്ഷണം ഉണ്ടായിരുന്നു. അത് പൊടിച്ചു. അൽപ സമയശേഷം ഒരു പൊക്കമുള്ള ബഹുദൈവ വിശ്വാസി കുറേ ആടുകളെ മേച്ചുകൊണ്ട് വന്നു. നബി(സ) ചോദിച്ചു: "വിൽപനക്കോ ദാനത്തിനോ." അവൻ പറഞ്ഞു: വിൽപനക്കാണ്. അയാളിൽനിന്നും നബി(സ) ഒരു ആടിനെ വാങ്ങി. അതിനെ വേവിക്കുകയും അതിന്റെ കരളെടുത്ത് ചുടുവാൻ നബി(സ) കൽപിക്കുകയും ചെയ്തു. അല്ലാഹുവാണ, അതിന്റെ കരളിൽ നിന്നും നൂറ്റിമുപ്പതു പേർക്കും ഓരോ കഷ്ണം നബി(സ) മുറിച്ചു കൊടുത്തു. സദസ്സിലുള്ളവർക്ക് അപ്പോൾ തന്നെ നൽകുകയും ഇല്ലാത്തവർക്ക് സൂക്ഷിച്ചു വെക്കുകയും ചെയ്തു. അങ്ങനെ അവിടുന്ന് അത് രണ്ടു തളികകളിലാക്കി. അങ്ങനെ എല്ലാവരും ഭക്ഷിക്കുകയും ഞങ്ങളുടെ വയറുകൾ നിറയുകയും ചെയ്തു. എന്നിട്ടും പാത്രത്തിൽ ബാക്കിയായി. ശേഷം അത് ഞങ്ങൾ ഒട്ടകപ്പുറത്ത് കൊണ്ടുപോയി. അല്ലെങ്കിൽ നിവേദകൻ പറഞ്ഞതുപോലെ. (ബു)', 'عَبْدالرَّحْمَنِ بْنِ أَبِي بَكْرٍ', 'അബ്ദുർറഹ്മാനുബ്നു അബീബക്ർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 863, 863, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَتْ: قَدِمَتْ عَلَيَّ أُمِّي وَهِيَ مُشْرِكَةٌ فِي عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَفْتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قُلْتُ: إِنَّ أُمِّي قَدِمَتْ وَهِيَ رَاغِبَةٌ، أَفَأَصِلُ أُمِّي؟ قَالَ: "نَعَمْ، صِلِي أُمَّكِ". (خ)', 'അസ്മാഅ് ബിൻതുഅബീബക്ർ(റ): റസൂൽ(സ)യുടെ കാലത്ത് ബഹുദൈവ വിശ്വാസിയായ എന്റെ ഉമ്മ എന്റെ അരികൽ വന്നു. ആ വിഷയത്തിൽ ഞാൻ റസൂൽ(സ)യോട് വിധി ആരാഞ്ഞു. ഞാൻ ചോദിച്ചു. എന്റെ ഉമ്മ ആഗ്രഹപൂർവ്വം എന്നിലേക്ക് വന്നിരിക്കുന്നു, ഉമ്മയുമായി ഞാൻ ബന്ധം പുലർത്തേണ്ടതുണ്ടോ? നബി(സ) പറഞ്ഞു: "നിന്റെ ഉമ്മയുമായി നീ ബന്ധം ചേർക്കുക." (ബു)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻതുഅബീബക്ർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ عَبْد الله بْن عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ شَهِدَ عِنْدَ مَرْوَانَ لِبَنِي صُهَيْبٍ: أَنَّ رَسُولَ الله أَعْطَى صُهَيْبًا بَيْتَيْنِ وَحُجْرَةً، فَقَضَى مَرْوَانُ بِشَهَادَته لَهُمْ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): സ്വുഹൈബ്(റ)വിന് റസൂൽ(സ) രണ്ടു വീടുകളും ഒരു മുറിയും നൽകി എന്ന് സ്വൂഹൈബ്(റ)വിന്റെ സന്താനങ്ങൾക്കുവേണ്ടി മർവാന്റെ സന്നിധിയിൽ അദ്ദേഹം സാക്ഷി പറഞ്ഞു. അപ്പോൾ അവർക്കു വേണ്ടിയുള്ള അദ്ദേഹത്തിന്റെ സാക്ഷിത്വം മർവാൻ സ്വീകരിച്ചു. (ബു)', 'عَبْد الله بْن عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهُ دَخَلَ عَلَيْهَا أَيْمَنُ وَعَلَيْهَا دِرْعٌ مِنْ قِطْرٍ، وَفِي رِوَايَة: مِنْ قُطْنٍ، ثَمَنُهُ خَمْسَةُ دَرَاهِمَ، فَقَالَتْ: ارْفَعْ بَصَرَكَ إِلَى جَارِيَتِي، انْظُرْ إِلَيْهَا، فَإِنَّهَا تُزْهَى أَنْ تَلْبَسَهُ فِي الْبَيْت، وَقَدْ كَانَ لِي مِنْهُنَّ دِرْعٌ عَلَى عَهْد رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَا كَانَت امْرَأَةٌ تُقَيَّنُ بِالْمَدِينَة إِلَّا أَرْسَلَتْ إِلَيَّ تَسْتَعِيرُهُ. (خ)', 'ആഇശ(റ): ഒരിക്കൽ ഐമൻ(റ) ആഇശ(റ)യുടെ വീട്ടിൽ ചെന്നു. അഞ്ച് ദിർഹം വിലയുള്ള പരുക്കൻ നൂലുകൊണ്ട്, മറ്റൊരു നിവേദനത്തിൽ: പരുത്തികൊണ്ട്, നെയ്ത ഒരു വസ്ത്രമാണ് മഹതി അപ്പോൾ ധരിച്ചിരുന്നത്. ആഇശ(റ) പറഞ്ഞു: എന്റെ പരിചാരികയുടെ നേരെ നിങ്ങളൊന്ന് കണ്ണുയർത്തി നോക്കു. വീട്ടിൽ നിൽക്കുമ്പോൾ ഈ സത്രം ധരിക്കുന്നതിൽ അവൾ മേന്മ നടിക്കുകയാണ്. റസൂൽ(സ)യുടെ കാലത്ത് ഈ ഇനത്തിൽപ്പെട്ട ഒരു വസ്തം എനിക്കുണ്ടായിരുന്നു. മദീനയിൽ ചമയിക്കപ്പെടുന്ന ഏതൊരു പെണ്ണും അത് വായ്പ വാങ്ങാൻ എന്റടുത്തേക്ക് ആളെ അയക്കുമായിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 864, 864, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=18), 1, 'وَفِي رِوَايَةٍ: مِنْ قُطْنٍ، ثَمَنُهُ خَمْسَةُ دَرَاهِمَ، فَقَالَتْ: ارْفَعْ بَصَرَكَ إِلَى جَارِيَتِي، انْظُرْ إِلَيْهَا، فَإِنَّهَا تُزْهَى أَنْ تَلْبَسَهُ فِي الْبَيْت، وَقَدْ كَانَ لِي مِنْهُنَّ دِرْعٌ عَلَى عَهْد رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَا كَانَت امْرَأَةٌ تُقَيَّنُ بِالْمَدِينَة إِلَّا أَرْسَلَتْ إِلَيَّ تَسْتَعِيرُهُ. (خ)', 'മറ്റൊരു നിവേദനത്തിൽ: പരുത്തികൊണ്ട്, നെയ്ത ഒരു വസ്ത്രമാണ് മഹതി അപ്പോൾ ധരിച്ചിരുന്നത്. ആഇശ(റ) പറഞ്ഞു: എന്റെ പരിചാരികയുടെ നേരെ നിങ്ങളൊന്ന് കണ്ണുയർത്തി നോക്കു. വീട്ടിൽ നിൽക്കുമ്പോൾ ഈ സത്രം ധരിക്കുന്നതിൽ അവൾ മേന്മ നടിക്കുകയാണ്. റസൂൽ(സ)യുടെ കാലത്ത് ഈ ഇനത്തിൽപ്പെട്ട ഒരു വസ്തം എനിക്കുണ്ടായിരുന്നു. മദീനയിൽ ചമയിക്കപ്പെടുന്ന ഏതൊരു പെണ്ണും അത് വായ്പ വാങ്ങാൻ എന്റടുത്തേക്ക് ആളെ അയക്കുമായിരുന്നു. (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَنَسِ بْنِ مَالك رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا قَدِمَ الْمُهَاجِرُونَ الْمَدِينَةَ مِنْ مَكَّةَ، وَلَيْسَ بِأَيْدِيهِمْ يَعْنِي شَيْئًا، وَكَانَتِ الْأَنْصَارُ أَهْلَ الْأَرْضِ وَالْعَقَارِ، فَقَاسَمَهُمُ الْأَنْصَارُ عَلَى أَنْ يُعْطُوهُمْ ثِمَارَ أَمْوَالِهِمْ كُلَّ عَامٍ، وَيَكْفُوهُمُ الْعَمَلَ وَالْمَئُونَةَ، وَكَانَتْ أُمُّهُ أُمُّ أَنَسٍ أُمُّ سُلَيْمٍ كَانَتْ أُمَّ عَبْداللَّه بْنِ أَبِي طَلْحَةَ، فَكَانَتْ أَعْطَتْ أُمُّ أَنَسٍ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِذَاقًا، فَأَعْطَاهُنَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُمَّ أَيْمَنَ مَوْلَاتَهُ أُمَّ أُسَامَةَ بْنِ زَيْد، قَالَ أَنَسُ بْنُ مَالك: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا فَرَغَ مِنْ قَتْلِ أَهْلِ خَيْبَرَ، فَانْصَرَفَ إِلَى الْمَدِينَة، رَدَّ الْمُهَاجِرُونَ إِلَى الْأَنْصَارِ مَنَائِحَهُمِ الَّتِي كَانُوا مَنَحُوهُمْ مِنْ ثِمَارِهِمْ، فَرَدَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أُمِّه عِذَاقَهَا، وَأَعْطَى رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُمَّ أَيْمَنَ مَكَانَهُنَّ مِنْ حَائِطه. (خ)', 'അനസുബ്നു മാലിക്(റ): മുഹാജിറുകൾ മക്കയിൽനിന്ന് മദീനയിലെത്തിയപ്പോൾ അവരുടെ പക്കൽ ഒന്നുമുണ്ടായിരുന്നില്ല. അൻസ്വാറുകളാണെങ്കിൽ ഭൂമിയും തോട്ടങ്ങളും ഉള്ളവരായിരുന്നു. അങ്ങനെ വർഷംതോറും ഫലത്തിന്റെ പകുതി നൽകണമെന്ന വ്യവസ്ഥയിൽ അൻസ്വാറുകൾ മുഹാജിറുകൾക്ക് ഭൂമികൾ പാട്ടത്തിനു നൽകി. മുഹാജിറുകൾ അതിലെ ജോലികളും ചെലവുകളും വഹിക്കുകയും ചെയ്യണം. ഉമ്മുസുലൈം(റ) എന്നറിയപ്പെടുന്ന അനസ്(റ)വിന്റെ മാതാവ് അബ്ദുല്ലാഹിബ്നു അബീത്വൽഹ(റ)വിന്റെ മാതാവ് കൂടിയായിരുന്നു. അനസ്(റ)വിന്റെ മാതാവ് റസൂൽ(സ)ക്ക് തന്റെ ഒരു ഈത്തപ്പനത്തോട്ടം നൽകിയിട്ടുണ്ടായിരുന്നു. റസൂൽ(സ) അത് ഉസാമതുബ്നു സൈദ്(റ)വിന്റെ മാതാവും തന്റെ സേവകയുമായ ഉമ്മുഐമൻ(റ)യ്ക്ക് നൽകി. അനസുബ്നു മാലിക്(റ) പറഞ്ഞു: നിശ്ചയം നബി(സ) ഖൈബറുകാരോടുള്ള പോരാട്ടത്തിൽനിന്ന് വിരമിക്കുകയും മദീനയിലേക്ക് മടങ്ങുകയും ചെയ്തപ്പോൾ, അൻസ്വാറുകൾ നൽകിയിരുന്ന തങ്ങളുടെ ഫലവൃക്ഷങ്ങളിൽപെട്ട പാട്ട മുതലുകളെല്ലാം മുഹാജിറുകൾ തിരിച്ചു നൽകി. അപ്പോൾ റസൂൽ(സ) അനസ്(റ)വിന്റെ ഉമ്മാക്ക് അവരുടെ ഈത്തപ്പനകൾ തിരിച്ചു നൽകുകയും അതിനു പകരമായി ഉമ്മുഐമൻ(റ)യ്ക്ക് തന്റെ തോട്ടത്തിന്റെ ഒരു ഭാഗം നൽകുകയും ചെയ്തു. (ബു)', 'أَنَسِ بْنِ مَالك', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 864, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَبْد اللَّه بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "أَرْبَعُون خَصْلَة: أَعْلَاهُنَّ مَنِيحَةُ الْعَنْز، مَا منْ عَامل يَعْمَلُ بخَصْلَة منْهَا رَجَاءَ ثَوَابهَا وَتَصْدِيقَ مَوْعُودهَا، إِلَّا أَدْخَلَهُ اللَّهُ بهَا الْجَنَّةَ". (خ)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നാൽപ്പത് കാര്യങ്ങളുണ്ട്: അവയിൽ ഏറ്റവും ഉത്തമമായത്, പാൽ ചുരത്തുന്ന ആടിനെ ഉപകാരമെടുക്കുന്നതിനായി നൽകലാണ്. അവയിൽ ഏതൊരു കാര്യവും, അതിന്റെ പ്രതിഫലത്തെയും അതിനാൽ വാഗ്ദാനം ചെയ്യപ്പെട്ടതിനെയും പ്രതീക്ഷിച്ചുകൊണ്ട് ഒരാൾ പ്രവർത്തിക്കുന്നുവെങ്കിൽ, അതു കാരണത്താൽ അവനെ അല്ലാഹു സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കാതിരിക്കുകയില്ല." (ബു)', 'عَبْد اللَّه بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ كَانَ يَقْبَلُ الْهَدِيَّةَ وَيُثِيبُ عَلَيْهَا. (خ,د,ت)', 'ആഇശ(റ): നിശ്ചയം നബി(സ) പാരിതോഷികം സ്വീകരിക്കുകയും അതിന് പകരം നൽകുകയും ചെയ്യാറുണ്ടായിരുന്നു. (ബു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د','ت']::text[], array['ബു','ദ','തു']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "إِذَا مَاتَ الْإِنْسَانُ انْقَطَعَ عَنْهُ عَمَلُهُ إِلَّا منْ ثَلَاثَة: إِلَّا منْ صَدَقَة جَارِيَة، أَوْ علْم يُنْتَفَعُ به، أَوْ وَلَد صَالح يَدْعُو لَهُ". (م)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "മനുഷ്യൻ മരിച്ചാൽ മൂന്ന് കാര്യങ്ങളിൽ നിന്നൊഴികെ അവന്റെ കർമ്മങ്ങൾ മുറിയും: നിലനിൽക്കുന്ന ദാനം, ഉപകാരപ്രതമായ വിജ്ഞാനം, തനിക്കുവേണ്ടി പ്രാർത്ഥിക്കുന്ന നല്ല സന്താനം എന്നിവയാണവ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "الرَّجُلُ أَحَقُّ بِهِبَتِه مَا لَمْ يُثَبْ مِنْهَا". [ز: في إسناده ضعيف]. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പാരിതോഷികത്തിന് പകരം നൽകപ്പെടാത്തിടത്തോളം കാലം അതുമായി ഏറ്റവും ബന്ധപ്പെട്ടവൻ അത് നൽകിയവനാണ്." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 865, 865, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "مَنْ شَفَعَ لِأَخِيه بِشَفَاعَة، فَأَهْدَى لَهُ هَدِيَّةً عَلَيْهَا فَقَبِلَهَا، فَقَدْ أَتَى بَابًا عَظِيمًا منْ أَبْوَاب الرِّبَا". (د)', 'അബൂഉമാമ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ സഹോദരനു വേണ്ടി വല്ല ശിപാർശയും നടത്തുകയും, അതിനു പകരമായി അവന് വല്ല പാരിതോഷികവും നൽകുകയും അവനത് സ്വീകരിക്കുകയും ചെയ്താൽ, പലിശയുടെ കവാടങ്ങളിൽ ഗൗരവമേറിയ ഒരു കവാടത്തിലേക്കാണ് അവൻ ചെന്നിരിക്കുന്നത്." (ദ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 865, 866, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ أَتَتْهُ وَفْدُ هَوَازِنَ، فَقَالُوا: يَا مُحَمَّدُ، إِنَّا أَصْلٌ وَعَشِيرَةٌ، وَقَدْ نَزَلَ بِنَا مِنَ الْبَلَاءِ مَا لَا يَخْفَى عَلَيْكَ، فَامْنُنْ عَلَيْنَا مَنَّ اللَّهُ عَلَيْكَ، فَقَالَ: "اخْتَارُوا مِنْ أَمْوَالِكُمْ، أَوْ مِنْ نِسَائِكُمْ وَأَبْنَائِكُمْ". فَقَالُوا: قَدْ خَيَّرْتَنَا بَيْنَ أَحْسَابِنَا وَأَمْوَالِنَا، بَلْ نَخْتَارُ نِسَاءَنَا وَأَبْنَاءَنَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا مَا كَانَ لِي وَلِبَنِي عَبْدِ الْمُطَّلِبِ فَهُوَ لَكُمْ، فَإِذَا صَلَّيْتُ الظُّهْرَ فَقُومُوا فَقُولُوا: إِنَّا نَسْتَعِينُ بِرَسُولِ اللَّهِ عَلَى الْمُؤْمِنِينَ – أَوِ: الْمُسْلِمِينَ – فِي نِسَائِنَا وَأَبْنَائِنَا". فَلَمَّا صَلَّوُا الظُّهْرَ قَامُوا فَقَالُوا ذَلِكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَمَا كَانَ لِي وَلِبَنِي عَبْدِ الْمُطَّلِبِ فَهُوَ لَكُمْ". فَقَالَ الْمُهَاجِرُونَ: وَمَا كَانَ لَنَا فَهُوَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَتِ الْأَنْصَارُ: مَا كَانَ لَنَا فَهُوَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ الْأَقْرَعُ بْنُ حَابِسٍ: أَمَّا أَنَا وَبَنُو تَمِيمٍ فَلَا. وَقَالَ عُيَيْنَةُ بْنُ حِصْنٍ: أَمَّا أَنَا وَبَنُو فَزَارَةَ فَلَا. وَقَالَ الْعَبَّاسُ بْنُ مِرْدَاسٍ: أَمَّا أَنَا وَبَنُو سُلَيْمٍ فَلَا. فَقَامَتْ بَنُو سُلَيْمٍ، فَقَالُوا: كَذَبْتَ، مَا كَانَ لَنَا فَهُوَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا أَيُّهَا النَّاسُ، رُدُّوا عَلَيْهِمْ نِسَاءَهُمْ وَأَبْنَاءَهُمْ، فَمَنْ تَمَسَّكَ مِنْ هَذَا الْفَيْءِ بِشَيْءٍ فَلَهُ سِتُّ فَرَائِضَ مِنْ أَوَّلِ شَيْءٍ يُفِيئُهُ اللَّهُ عَزَّ وَجَلَّ عَلَيْنَا". وَرَكِبَ رَاحِلَتَهُ، وَرَكِبَ النَّاسُ: اقْسِمْ عَلَيْنَا فَيْئَنَا، فَأَلْجَئُوهُ إِلَى شَجَرَةٍ، فَخَطِفَتْ رِدَاءَهُ، فَقَالَ: "يَا أَيُّهَا النَّاسُ، رُدُّوا عَلَيَّ رِدَائِي، فَوَاللَّهِ لَوْ أَنَّ لَكُمْ شَجَرَ تِهَامَةَ نَعَمًا، قَسَمْتُهُ عَلَيْكُمْ، ثُمَّ لَمْ تَلْقَوْنِي بَخِيلًا وَلَا جَبَانًا وَلَا كَذُوبًا". ثُمَّ أَتَى بَعِيرًا فَأَخَذَ مِنْ سَنَامِهِ وَبَرَةً بَيْنَ أُصْبُعَيْهِ، ثُمَّ يَقُولُ: "هَا، إِنَّهُ لَيْسَ لِي مِنَ الْفَيْءِ شَيْءٌ وَلَا هَذِهِ إِلَّا خُمُسٌ، وَالْخُمُسُ مَرْدُودٌ فِيكُمْ". فَقَامَ إِلَيْهِ رَجُلٌ بِكُبَّةٍ مِنْ شَعَرٍ فَقَالَ: يَا رَسُولَ اللَّهِ، أَخَذْتُ هَذِهِ لِأُصْلِحَ بِهَا بَرْدَعَةَ بَعِيرٍ لِي. فَقَالَ: "أَمَّا مَا كَانَ لِي وَلِبَنِي عَبْدِ الْمُطَّلِبِ فَهُوَ لَكَ". فَقَالَ: أَوَبَلَغَتْ هَذِهِ؟ فَلَا أَرَبَ لِي فِيهَا، فَنَبَذَهَا. وَقَالَ: "يَا أَيُّهَا النَّاسُ، أَدُّوا الْخِيَاطَ وَالْمَخِيطَ، فَإِنَّ الْغُلُولَ يَكُونُ عَلَى أَهْلِهِ عَارًا وَشَنَارًا يَوْمَ الْقِيَامَةِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഞങ്ങൾ പ്രവാചകർ(സ)യുടെ അരികെയായിരുന്നു. തൽസമയം ഹവാസിൻ ഗോത്രത്തിലെ ഒരു സംഘമാളുകൾ അവിടെ വന്നു. അവർ പറഞ്ഞു: ഓ മുഹമ്മദ്, ഞങ്ങൾ പാരമ്പര്യമുള്ള ഒരു ഗോത്രക്കാരാണ്. താങ്കൾക്ക് ഗോപ്യമാവാത്ത വിധം ഞങ്ങൾക്കിതാ പല ബുദ്ധിമുട്ടുകളും ഇറങ്ങിയിരിക്കുന്നു. അതിനാൽ ഞങ്ങൾക്കുവേണ്ടി നന്മ ചെയ്തു തരണം. അല്ലാഹു താങ്കൾക്കും ഗുണം ചെയ്യട്ടെ. പ്രവാചകർ(സ) പ്രതിവചിച്ചു: "നിങ്ങളുടെ സമ്പത്തിൽ നിന്നും ഭാര്യാസന്താനങ്ങളിൽ നിന്നും ഏതെങ്കിലുമൊന്ന് തെരെഞ്ഞെടുക്കുക." അവർ പറഞ്ഞു: താങ്കൾ ഞങ്ങൾക്ക് കുടുംബത്തിന്റെയും സമ്പത്തിന്റെയും ഇടയിലാണ് ഹിതം തന്നിരിക്കുന്നത്. എന്നാൽ ഞങ്ങൾ തെരെഞ്ഞെടുക്കുന്നത് ഞങ്ങളുടെ ഭാര്യാ സന്താനങ്ങളെയാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എനിക്കും അബ്ദുൽ മുത്ത്വലിബിന്റെ സന്താനങ്ങൾക്കുമുള്ളത് നിങ്ങളുടേതുമാണ്. ആയതിനാൽ ഞാൻ ളുഹ്റ് നിസ്കരിച്ചു കഴിഞ്ഞാൽ നിങ്ങൾ എഴുന്നേറ്റ് പറയുക: ഞങ്ങളുടെ സ്ത്രീകളുടെയും കുട്ടികളുടെയും കാര്യത്തിൽ അല്ലാഹുവിന്റെ ദൂതർ മുഖേന സത്യവിശാസികളോട് - അല്ലെങ്കിൽ മുസ്ലിംകളോട് - ഞങ്ങൾ സഹായം തേടുന്നു." അങ്ങനെ ളുഹ്ർ നിസ്കാരശേഷം അവർ എഴുന്നേറ്റ് നബി(സ) നിർദ്ദേശിച്ചതുപ്രകാരം പറഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എനിക്കും അബ്ദുൽ മുത്ത്വലിബിന്റെ സന്താനങ്ങൾക്കുമുള്ളത് നിങ്ങളുടേതുമാണ്." അപ്പോൾ മുഹാജിറുകൾ പറഞ്ഞു: ഞങ്ങൾക്കുള്ളതെല്ലാം റസൂൽ(സ)ക്കുള്ളതാണ്. അൻസ്വാരികൾ പറഞ്ഞു: ഞങ്ങൾക്കുള്ളതെല്ലാം റസൂൽ(സ)ക്കുള്ളതാണ്. അപ്പോൾ അഖ്റഉബ്നു ഹാബിസ്(റ) പറഞ്ഞു: എന്നാൽ ഞാനും ബനൂതമീമും അപ്രകാരമല്ല. ഉയൈനതുബ്നു ഹിസ്ൻ(റ) പറഞ്ഞു: ഞാനും ബനൂഫസാറ ഗോത്രവും അപ്രകാരമല്ല. അബ്ബാസുബ്നു മിർദാസ്(റ) പറഞ്ഞു: ഞാനും ബനൂസുലൈം ഗോത്രവും അപ്രകാരമല്ല. ഉടനെ ബനൂസുലൈം ഗോത്രക്കാർ എഴുന്നേറ്റ് പറഞ്ഞു: നീ പറഞ്ഞത് കള്ളമാണ്. ഞങ്ങൾക്കുള്ളതെല്ലാം റസൂൽ(സ)ക്കുള്ളതാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഓ ജനങ്ങളേ, അവരുടെ സ്ത്രീകളെയും സന്താനങ്ങളെയും തിരിച്ചു നൽകുക. ഈ ഫൈഇ¹ൽ നിന്ന് വല്ലതിനെയും ആരെങ്കിലും പിടിച്ചു വെക്കുന്നുവെങ്കിൽ, നമുക്ക് ഇനി ആദ്യമായി അല്ലാഹു നൽകുന്ന ഫൈഇൽ നിന്ന് അവന് ആറ് ഓഹരി ഉണ്ടായിരിക്കുന്നതാണ്." അങ്ങനെ റസൂൽ(സ) തന്റെ വാഹനത്തിൽ കയറി. തങ്ങളുടെ യുദ്ധമുതൽ വീതിച്ചു തരണം എന്ന് ആവശ്യപ്പെട്ടുകൊണ്ട് ജനങ്ങളും വാഹനം കയറി. അങ്ങനെ അവർ റസൂൽ(സ)യെ ഒരു മരത്തിന്റെ അടുത്തേക്ക് എത്തിക്കുകയും അവിടുത്തെ തട്ടം മരത്തിൽ തങ്ങുകയും ചെയ്തു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ജനങ്ങളേ, എന്റെ തട്ടം തിരിച്ചു നൽകുക, അല്ലാഹുവാണ, തിഹാമയിലെ മരങ്ങൾ കണക്കെ നിങ്ങൾക്ക് ഒട്ടകങ്ങളുണ്ടെങ്കിൽ അവയെല്ലാം ഞാൻ നിങ്ങൾക്ക് വീതിച്ചു നൽകും. ശേഷം പിശുക്കനോ ഭീരുവോ കള്ളം പറയുന്നവനോ ആയി നിങ്ങൾ എന്നെ കാണുകയില്ല." ശേഷം റസൂൽ(സ) ഒരു ഒട്ടകത്തിന്റെ അടുത്ത് ചെന്ന് അതിന്റെ പൂഞ്ഞയിൽനിന്ന് ഒരു രോമമെടുത്ത് രണ്ടു വിരലുകൾക്കിടയിൽ വെച്ചുകൊണ്ട് പറഞ്ഞു: "അറിയുക, ഫൈഇൽ നിന്ന് ഇത്രപോലും എനിക്ക് അനുവദനീയമല്ല, അഞ്ചിലൊന്ന് ഒഴികെ. അഞ്ചിലൊന്നാണെങ്കിൽ നിങ്ങളിലേക്കു തന്നെ മടക്കപ്പെടുന്നതാണ്." ഉടനെ ഒരാൾ ഒരു കെട്ട് രോമവുമായി എഴുന്നേറ്റു കൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ ഒട്ടകത്തിന്റെ ജീനി ശരിപ്പെടുത്താൻ വേണ്ടി (യുദ്ധമുതലിൽ നിന്ന്) ഞാൻ എടുത്തതാണിത്. റസൂൽ(സ) പറഞ്ഞു: "എനിക്കും അബ്ദുൽമുത്ത്വലിബിന്റെ സന്താനങ്ങൾക്കും ഉള്ളത് നിനക്കാണ്." അപ്പോൾ അയാൾ പറഞ്ഞു: അത് ഇത്രത്തോളും ഉണ്ടോ? എങ്കിൽ എനിക്ക് ഇത് ആവശ്യമില്ല. അങ്ങനെ അയാൾ അത് ഉപേക്ഷിച്ചു. റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങളേ, നൂലും സൂചിയും നിങ്ങൾ തിരിച്ചേൽപിക്കുക. നിശ്ചയം വഞ്ചിച്ചെടുത്ത മുതൽ അതിന്റെ ഉടമക്ക് അന്ത്യനാളിൽ നിന്ദ്യതയും അപമാനവും ആയിരിക്കും." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', '¹. യുദ്ധം ചെയ്യാതെ ലഭിക്കുന്ന ശത്രുവിന്റെ മുതൽ.', null, array['ن']::text[], array['ന']::text[], null, null, 866, 867, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبْد اللَّه بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "مَثَلُ الَّذي يَسْتَرِدُّ مَا وَهَبَ كَمَثَلِ الْكَلْب يَقِيءُ فَيَأْكُلُ قَيْئَهُ، فَإِذَا اسْتَرَدَّ الْوَاهِبُ فَلْيُوَقَّفْ فَلْيُعَرَّفْ بِمَا اسْتَرَدَّ، ثُمَّ لِيُدْفَعْ إِلَيْه مَا وَهَبَ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ദാനം നൽകിയതിനെ തിരിച്ചു ചോദിക്കുന്നവന്റെ ഉപമ, ഛർദ്ദിക്കുകയും പിന്നെ അതുതന്നെ ഭക്ഷിക്കുകയും ചെയ്യുന്ന നായയെപ്പോലെയാണ്. ദാനം നൽകിയവൻ അത് തിരിച്ചു ചോദിച്ചാൽ അവനെ നിർത്തി അവൻ തിരികെ ചോദിച്ച കാര്യം പരസ്യപ്പെടുത്തപ്പെടുകയും ശേഷം അവൻ നൽകിയത് തിരിച്ചു നൽകപ്പെടുകയും ചെയ്യണം." (ദ,ജ)', 'عَبْد اللَّه بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 867, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنِ ابْنِ عُمَرَ، وَابْنِ عَبَّاسٍ – رَضِيَ اللَّهُ عَنْهُمْ – يَرْفَعَانِ الْحَدِيثَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَحِلُّ لِرَجُلٍ يُعْطِي عَطِيَّةً – وَفِي رِوَايَةٍ: أَنْ يَهَبَ هِبَةً – ثُمَّ يَرْجِعُ فِيهَا، إِلَّا الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ، وَمَثَلُ الَّذِي يُعْطِي عَطِيَّةً ثُمَّ يَرْجِعُ فِيهَا كَمَثَلِ الْكَلْبِ: أَكَلَ حَتَّى إِذَا شَبِعَ قَاءَ، ثُمَّ عَادَ فِي قَيْئِهِ". (د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ), ഇബ്നുഅബ്ബാസ്(റ) എന്നിവർ നബി(സ)യിലേക്ക് ചേർത്തി ഹദീസ് പറയുന്നു: നബി(സ) പറഞ്ഞു: "ദാനം നൽകുന്ന - മറ്റൊരു നിവേദനം: പാരിതോഷികം നൽകുന്ന - വ്യക്തി അതിൽ നിന്ന് പിന്മാറൽ (തിരിച്ചു ചോദിക്കൽ) അനുവദനീയമല്ല. ഒരു പിതാവ് തന്റെ മകന് നൽകുന്നതിലൊഴികെ. ദാനം നൽകിയ ശേഷം അതിൽനിന്ന് പിന്മാറുന്നവന്റെ ഉപമ നായയെപ്പോലെയാണ്: അതു ഭക്ഷിക്കുന്നു, വയർ നിറയുമ്പോൾ ഛിർദ്ദിക്കുകയും ശേഷം ഛർദ്ദിച്ചതിലേക്കു തന്നെ മടങ്ങുകയും ചെയ്യുന്നു." (ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ، وَابْنِ عَبَّاسٍ –', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=27), 1, 'وَفِي رِوَايَةٍ: أَنْ يَهَبَ هِبَةً – ثُمَّ يَرْجِعُ فِيهَا، إِلَّا الْوَالِدَ فِيمَا يُعْطِي وَلَدَهُ، وَمَثَلُ الَّذِي يُعْطِي عَطِيَّةً ثُمَّ يَرْجِعُ فِيهَا كَمَثَلِ الْكَلْبِ: أَكَلَ حَتَّى إِذَا شَبِعَ قَاءَ، ثُمَّ عَادَ فِي قَيْئِهِ". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: പാരിതോഷികം നൽകുന്ന - വ്യക്തി അതിൽ നിന്ന് പിന്മാറൽ (തിരിച്ചു ചോദിക്കൽ) അനുവദനീയമല്ല. ഒരു പിതാവ് തന്റെ മകന് നൽകുന്നതിലൊഴികെ. ദാനം നൽകിയ ശേഷം അതിൽനിന്ന് പിന്മാറുന്നവന്റെ ഉപമ നായയെപ്പോലെയാണ്: അതു ഭക്ഷിക്കുന്നു, വയർ നിറയുമ്പോൾ ഛിർദ്ദിക്കുകയും ശേഷം ഛർദ്ദിച്ചതിലേക്കു തന്നെ മടങ്ങുകയും ചെയ്യുന്നു." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ عَبْد اللَّه بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَثَلُ الَّذي يَرْجِعُ فِي صَدَقَته كَمَثَلِ الْكَلْب: يَرْجِعُ فِي قَيْئه فَيَأْكُلُهُ". وَفِي رِوَايَة: "يَقِيءُ ثُمَّ يَعُودُ فِي قَيْئه". وَفِي رِوَايَة: "مَثَلُ الَّذي يَتَصَدَّقُ بالصَّدَقَة ثُمَّ يَرْجِعُ فيهَا كَمَثَل الْكَلْب: قَاءَ ثُمَّ عَادَ في قَيْئه فَأَكَلَهُ". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ദാനം നൽകിയതിൽ നിന്നു പിന്മാറുന്നവന്റെ ഉപമ, ഛർദ്ദിച്ചതിലേക്ക് തിരികെ ചെന്ന് അതു ഭക്ഷിക്കുന്ന നായയെപ്പോലെയാണ്." മറ്റൊരു നിവേദനം: "ഛർദ്ദിക്കുകയും ശേഷം ഛർദ്ദിച്ചതിലേക്ക് തിരികെ ചെല്ലുകയും ചെയ്യുന്ന (നായയെപ്പോലെ)." മറ്റൊരു നവേദനം: "ഒരു ദാനം നൽകിയ ശേഷം അതിൽനിന്ന് പിന്മാറുന്നവന്റെ ഉപമ നായയെപ്പോലെയാണ്: അത് ഛർദ്ദിച്ചു, ശേഷം ഛർദ്ദിച്ചതിലേക്കു ചെന്ന് അതു ഭക്ഷിച്ചു." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْد اللَّه بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=28), 1, 'وَفِي رِوَايَةٍ: "يَقِيءُ ثُمَّ يَعُودُ فِي قَيْئه".', 'മറ്റൊരു നിവേദനം: "ഛർദ്ദിക്കുകയും ശേഷം ഛർദ്ദിച്ചതിലേക്ക് തിരികെ ചെല്ലുകയും ചെയ്യുന്ന (നായയെപ്പോലെ)." മറ്റൊരു നവേദനം: "ഒരു ദാനം നൽകിയ ശേഷം അതിൽനിന്ന് പിന്മാറുന്നവന്റെ ഉപമ നായയെപ്പോലെയാണ്: അത് ഛർദ്ദിച്ചു, ശേഷം ഛർദ്ദിച്ചതിലേക്കു ചെന്ന് അതു ഭക്ഷിച്ചു." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=28), 2, 'وَفِي رِوَايَةٍ: "مَثَلُ الَّذي يَتَصَدَّقُ بالصَّدَقَة ثُمَّ يَرْجِعُ فيهَا كَمَثَل الْكَلْب: قَاءَ ثُمَّ عَادَ في قَيْئه فَأَكَلَهُ". (ق,د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "لَا تَعُدْ فِي صَدَقَتِكَ". (ق,ن,جه)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ദാനത്തിൽ നിന്ന് നീ പിന്മാറരുത് (തിരിച്ചു ചോദിക്കരുത്)." (ബു,മു,ന,ജ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: حَمَلْتُ عَلَى فَرَسٍ عَتِيقٍ فِي سَبِيلِ اللَّه، فَأَضَاعَهُ صَاحِبُهُ، فَظَنَنْتُ أَنَّهُ بَائعُهُ برُخْصٍ، فَسَأَلْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ عَنْ ذَلكَ، فَقَالَ: "لَا تَبْتَعْهُ، وَلَا تَعُدْ فِي صَدَقَتكَ، فَإِنَّ الْعَائدَ فِي صَدَقَته كَالْكَلْب يَعُودُ فِي قَيْئه". (ق,د)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (പോരാടുന്നതിനുവേണ്ടി) ഞാൻ വിലപിടിപ്പുള്ള ഒരു കുതിരയെ ദാനം നൽകി. എന്നാൽ അതിന്റെ ഉടമ അതിന്റെ പരിപാലനത്തിൽ വീഴ്ച വരുത്തി. അങ്ങനെ അദ്ദേഹം കുറഞ്ഞ വിലക്ക് അതിനെ വിൽക്കുമെന്ന് ഞാൻ ഭാവിച്ചു. അതിനെക്കുറിച്ച് ഞാൻ റസൂൽ(സ)യോട് ചോദിച്ചപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "താങ്കൾ അതിനെ വാങ്ങുകയോ, താങ്കളുടെ ദാനത്തെ തിരിച്ചു വാങ്ങുകയോ ചെയ്യരുത്. നിശ്ചയം തന്റെ ദാനത്തെ തിരിച്ചു വാങ്ങുന്നവൻ ഛർദ്ദിച്ചതിലേക്ക് തിരിച്ചു ചെല്ലുന്ന നായയെപ്പോലെയാണ്." (ബു,മു,ദ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 868, 868, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ، عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ تَصَدَّقَ بِفَرَسٍ عَلَى عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَبْصَرَ صَاحِبَهَا يَبِيعُهَا بِكَسْرٍ، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلَهُ عَنْ ذَلِكَ؟ فَقَالَ: "لَا تَبْتَعْ صَدَقَتَكَ". (جه)', 'ഉമർ(റ)വിൽനിന്ന് അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നിശ്ചയം അദ്ദേഹം റസൂൽ(സ)യുടെ കാലത്ത് ഒരു കുതിരയെ ദാനം ചെയ്യുകയും ശേഷം അതിന്റെ ഉടമ കുറഞ്ഞ വിലക്ക് അതിനെ വിൽക്കുന്നത് കാണുകയും ചെയ്തു. അപ്പോൾ നബി(സ)യുടെ അടുത്ത് ചെന്ന് അദ്ദേഹം അതിനെക്കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "നിന്റെ ദാനത്തെ നീ വാങ്ങരുത്." (ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ، عَنْ عُمَرَ', 'ഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ حَمَلَ عَلَى فَرَسٍ يُقَالُ لَهُ غَمْرٌ أَوْ غَمْرَةٌ، فَرَأَى مُهْرًا أَوْ مُهْرَةً مِنْ أَفْلَائِهَا يُبَاعُ، يُنْسَبُ إِلَى فَرَسِهِ، فَنَهَى عَنْهَا. (جه)', 'സുബൈറുബ്നുൽ അവ്വാം(റ): ''ഗ്വംറ്'' എന്നോ ''ഗ്വംറ'' എന്നോ പേരുള്ള ഒരു കുതിരയെ അദ്ദേഹം യുദ്ധത്തിനായി ദാനം നൽകി. ശേഷം അതിന്റെ കുട്ടികളിൽപെട്ട ഒരു ആൺകുതിരക്കുട്ടിയെ, അല്ലെങ്കിൽ പെൺകുതിരക്കുട്ടിയെ തന്റെ കുതിരയിലേക്ക് ചേർത്തു പറഞ്ഞുകൊണ്ട് വിൽക്കപ്പെടുന്നത് അദ്ദേഹം കണ്ടു. അപ്പോൾ അദ്ദേഹം അതു വിലക്കി. (ജ)', 'الزُّبَيْرِ بْنِ الْعَوَّامِ', 'സുബൈറുബ്നുൽ അവ്വാം(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ، إِنِّي تَصَدَّقْتُ عَلَى أُمِّي بِجَارِيَةٍ، وَإِنَّهَا مَاتَتْ. فَقَالَ: "آجَرَكِ اللهُ، وَرَدَّ عَلَيْكِ الْمِيرَاثَ". (م,ت,جه)', 'ബുറൈദ(റ): ഒരു സ്ത്രീ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, നിശ്ചയം ഞാൻ എന്റെ ഉമ്മാക്ക് ഒരു അടിമസ്ത്രീയെ ദാനമായി നൽകിയിരുന്നു, നിശ്ചയം അവർ മരിച്ചിരിക്കുന്നു. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അല്ലാഹു നിനക്ക് പ്രതിഫലം നൽകുകയും അനന്തരസ്വത്ത് തിരിച്ചു നൽകുകയും ചെയ്തിരിക്കുന്നു." (മു,തു,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي أَعْطَيْتُ أُمِّي حَدِيقَةً لِي، وَإِنَّهَا مَاتَتْ وَلَمْ تَتْرُكْ وَارِثًا غَيْرِي. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَجَبَتْ صَدَقَتُكِ، وَرَجَعَتْ إِلَيْكِ حَدِيقَتُكِ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: നിശ്ചയം ഞാൻ എന്റെ ഉമ്മാക്ക് ഒരു തോട്ടം ദാനമായി നൽകിയിരുന്നു. നിശ്ചയം ഞാനൊഴികെ ഒരു അനന്തരാവകാശിയും ഇല്ലാതെ അവർ മരിച്ചിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ദാനം പ്രതിഫലമുള്ളതാവുകയും നിന്റെ തോട്ടം നിനക്കുതന്നെ തിരിച്ചു ലഭിക്കുകയും ചെയ്തിരിക്കുന്നു." (ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 869, 869, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَجُوزُ لِامْرَأَةٍ هِبَةٌ فِي مَالِهَا إِذَا مَلَكَ زَوْجُهَا عِصْمَتَهَا". وَفِي رِوَايَةٍ قَالَ: لَمَّا فَتَحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ قَامَ خَطِيبًا، فَقَالَ فِي خُطْبَتِهِ: "لَا يَجُوزُ لِامْرَأَةٍ عَطِيَّةٌ إِلَّا بِإِذْنِ زَوْجِهَا". (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഭർത്താവ് തന്റെ ഉത്തരവാദിത്തം ഉടമപ്പെടുത്തിയ ശേഷം ഒരു സ്ത്രീക്കും തന്റെ മുതൽ ദാനം നൽകൽ അനുവദനീയമല്ല." മറ്റൊരു നിവേദനം: റസൂൽ(സ) മക്ക കീഴടക്കിയപ്പോൾ പ്രസംഗിക്കാൻവേണ്ടി എഴുന്നേറ്റു. അങ്ങനെ തന്റെ പ്രസംഗത്തിൽ അവിടുന്ന് പറഞ്ഞു: "ഭർത്താവിന്റെ സമ്മതത്തോടെയല്ലാതെ ഒരു സ്ത്രീക്കും ദാനം ചെയ്യൽ അനുവദനീയമല്ല." (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=35), 1, 'وَفِي رِوَايَةٍ قَالَ: لَمَّا فَتَحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ قَامَ خَطِيبًا، فَقَالَ فِي خُطْبَتِهِ: "لَا يَجُوزُ لِامْرَأَةٍ عَطِيَّةٌ إِلَّا بِإِذْنِ زَوْجِهَا". (د,ن,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) മക്ക കീഴടക്കിയപ്പോൾ പ്രസംഗിക്കാൻവേണ്ടി എഴുന്നേറ്റു. അങ്ങനെ തന്റെ പ്രസംഗത്തിൽ അവിടുന്ന് പറഞ്ഞു: "ഭർത്താവിന്റെ സമ്മതത്തോടെയല്ലാതെ ഒരു സ്ത്രീക്കും ദാനം ചെയ്യൽ അനുവദനീയമല്ല." (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَلْقَمَةَ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ وَفْدُ ثَقِيفٍ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُمْ هَدِيَّةٌ، فَقَالَ: "أَهَدِيَّةٌ أَمْ صَدَقَةٌ؟ فَإِنْ كَانَتْ هَدِيَّةٌ فَإِنَّمَا يُبْتَغَى بِهَا وَجْهُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَضَاءُ الْحَاجَةِ. وَإِنْ كَانَتْ صَدَقَةٌ فَإِنَّمَا يُبْتَغَى بِهَا وَجْهُ اللهِ عَزَّ وَجَلَّ". قَالُوا: لَا، بَلْ هَدِيَّةٌ. فَقَبِلَهَا مِنْهُمْ، وَقَعَدَ مَعَهُمْ يُسَائِلُهُمْ وَيُسَائِلُونَهُ، حَتَّى صَلَّى الظُّهْرَ مَعَ الْعَصْرِ. (ن)', 'അബ്ദുർഹ്മാനുബ്നു അൽഖമതുസ്സഖഫീ(റ): സഖീഫ് ഗോത്രത്തിലെ സംഘം റസൂൽ(സ)യുടെ അടുത്ത് വന്നപ്പോൾ അവരുടെ കൂടെ സമ്മാനവുമുണ്ടായിരുന്നു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "പാരിതോഷികമാണോ അതോ ദാനമാണോ? പാരിതോഷികമാണെങ്കിൽ അതുകൊണ്ട് അല്ലാഹുവിന്റെ റസൂലിന്റെ പ്രീതി കാംക്ഷിക്കപ്പെടുകയും മറ്റു ആവശ്യങ്ങൾ നടത്തുകയും ചെയ്യാം, ദാനമാണെങ്കിൽ അതുകൊണ്ട് അല്ലാഹുവിന്റെ പ്രീതി കാംക്ഷിക്കപ്പെടുകയേ ചെയ്യൂ." അവർ പറഞ്ഞു: അല്ല, പാരിതോഷികം തന്നെയാണ്. അങ്ങനെ റസൂൽ(സ) അവരിൽനിന്ന് അത് സ്വീകരിക്കുകയും അവരുടെ കൂടെ പരസ്പരം അന്വേഷണങ്ങൾ പറഞ്ഞുകൊണ്ട് ഇരിക്കുകയും അങ്ങനെ അസ്വറിനോടൊപ്പം ളുഹർ നമസ്കരിക്കുകയും ചെയ്തു. (ന)', 'عَبْدِ الرَّحْمَنِ بْنِ عَلْقَمَةَ الثَّقَفِيِّ', 'അബ്ദുർഹ്മാനുബ്നു അൽഖമതുസ്സഖഫീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَقَدْ هَمَمْتُ أَنْ لَا أَقْبَلَ هَدِيَّةً إِلَّا مِنْ قُرَشِيٍّ أَوْ أَنْصَارِيٍّ أَوْ ثَقَفِيٍّ أَوْ دَوْسِيٍّ". (د,ت,ن)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഖുറൈശിയോ അൻസ്വാരിയോ സഖഫിയോ ദൗസിയോ അല്ലാത്തവരിൽ നിന്ന് സമ്മാനം സ്വീകരിക്കുകയില്ലെന്ന് ഞാൻ തീരുമാനിച്ചിരിക്കുന്നു." (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِلَحْمٍ، فَقَالَ: "مَا هَذَا". فَقِيلَ: تُصُدِّقَ بِهِ عَلَى بَرِيرَةَ. فَقَالَ: "هُوَ لَهَا صَدَقَةٌ وَلَنَا هَدِيَّةٌ". (خ,ن)', 'അനസ്(റ): നിശ്ചയം റസൂൽ(സ)യുടെ അടുത്തേക്ക് അൽപം മാംസം കൊണ്ടുവരപ്പെട്ടു, അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "എന്താണിത്?" ബരീറ(റ)ക്ക് ദാനമായി ലഭിച്ചതാണ് എന്ന് മറുപടി പറയപ്പെട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അത് അവൾക്ക് ദാനവും നമുക്ക് സമ്മാനവുമാണ്." (ബു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 870, 870, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ خَيْرَةَ امْرَأَةِ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَتَتْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِحُلِيٍّ لَهَا فَقَالَتْ: إِنِّي تَصَدَّقْتُ بِهَذَا. فَقَالَ لَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَجُوزُ لِلْمَرْأَةِ فِي مَالِهَا إِلَّا بِإِذْنِ زَوْجِهَا، فَهَلِ اسْتَأْذَنْتِ كَعْبًا؟" قَالَتْ: نَعَمْ. فَبَعَثَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى كَعْبِ بْنِ مَالِكٍ زَوْجِهَا، فَقَالَ: "هَلْ أَذِنْتَ لِخَيْرَةَ أَنْ تَتَصَدَّقَ بِحُلِيِّهَا". فَقَالَ: نَعَمْ. فَقَبِلَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْهَا. [ز: في إسناده ضعيف] (جه)', 'കഅ്ബുബ്നു മാലിക്(റ)വിന്റെ ഭാര്യയായ ഖൈറ(റ): മഹതി തന്റെ ഒരു ആഭരണവുമായി റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: ഞാൻ ഇത് ദാനം ചെയ്തിരിക്കുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഭർത്താവിന്റെ അനുവാദമില്ലാതെ സ്ത്രീക്ക് തന്റെ മുതൽ ചെലവഴിക്കൽ അനുവദനീയമല്ല. നീ കഅ്ബിനോട് സമ്മതം ചോദിച്ചിട്ടുണ്ടോ?" മഹതി പറഞ്ഞു: അതെ. ഉടൻതന്നെ റസൂൽ(സ) അവരുടെ ഭർത്താവായ കഅ്ബുബ്നു മാലിക്(റ)വിന്റെ അടുത്തേക്ക് ആളെ അയച്ചുകൊണ്ട് ചോദിച്ചു: "ഖൈറക്ക് തന്റെ ആഭരണം ദാനം നൽകാൻ നീ അനുവാദനം നൽകിയിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. അപ്പോൾ റസൂൽ(സ) മഹതിയിൽനിന്ന് അത് സ്വീകരിച്ചു. ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'خَيْرَةَ امْرَأَةِ كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 870, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أَبَاهُ نَحَلَهُ نُحْلًا، فَقَالَتْ لَهُ أُمُّهُ: أَشْهِدِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى مَا نَحَلْتَ ابْنِي. فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَكَرِهَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَشْهَدَ لَهُ. (ن)', 'നുഅ്മാനുബ്നു ബശീർ(റ): നിശ്ചയം അദ്ദേഹത്തിന് തന്റെ പിതാവ് ഒരു വസ്തു ഭാഗിച്ചു. നൽകി². അപ്പോൾ അദ്ദേഹത്തിന്റെ ഉമ്മ പറഞ്ഞു: എന്റെ മകന് താങ്കൾ ഭാഗിച്ചു നൽകിയതിന് താങ്കൾ റസൂൽ(സ)യെ സാക്ഷി നിർത്തുക. ഉടനെ അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ചെന്ന് വിവരം പറഞ്ഞു. അപ്പോൾ തിരുമേനി(സ) അതിനു സാക്ഷി നിൽക്കുന്നതിന് നീരസം പ്രകടിപ്പിച്ചു. (ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', '² പ്രത്യുപകാരമില്ലാതെ ഭാഗിച്ചു നൽകുന്ന മുതലാണ് ''നുഹ്ൽ''.', null, array['ن']::text[], array['ന']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ بَشِيرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ نَحَلَ ابْنَهُ غُلَامًا، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَرَادَ أَنْ يُشْهِدَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "أَكُلَّ وَلَدِكَ نَحَلْتَهُ مِثْلَ ذَا". قَالَ: لَا. قَالَ: "فَارْدُدْهُ". وَفِي رِوَايَةٍ قَالَ: يَا نَبِيَّ اللهِ، نَحَلْتُ النُّعْمَانَ نَحْلَةً؟ قَالَ: "أَعْطَيْتَ لِإِخْوَتِهِ". قَالَ: لَا. قَالَ: "فَارْدُدْهُ". (ن)', 'ബശീർ(റ): നിശ്ചയം അദ്ദേഹം തന്റെ മകന് ഒരു അടിമയെ നൽകി. അങ്ങനെ അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ചെല്ലുകയും നബി(സ)യെ അക്കാര്യത്തിന് സാക്ഷി നിർത്തണമെന്ന് ആഗ്രഹിക്കുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "ഇതുപോലെ നിന്റെ എല്ലാ സന്താനങ്ങൾക്കും (ഭാഗം) നൽകിയിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "എങ്കിൽ അത് തിരിച്ചു വാങ്ങുക." മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, ഞാൻ നുഅ്മാന് ഒരു വസ്തു ഭാഗിച്ചു നൽകിയിട്ടുണ്ട്? നബി(സ) ചോദിച്ചു: "അവന്റെ സഹോദരങ്ങൾക്ക് നീ നൽകിയോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "എങ്കിൽ അത് തിരിച്ചു വാങ്ങുക." (ന)', 'بَشِيرٍ', 'ബശീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 871, 871, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=41), 1, 'وَفِي رِوَايَةٍ قَالَ: يَا نَبِيَّ اللهِ، نَحَلْتُ النُّعْمَانَ نَحْلَةً؟ قَالَ: "أَعْطَيْتَ لِإِخْوَتِهِ". قَالَ: لَا. قَالَ: "فَارْدُدْهُ". (ن)', 'മറ്റൊരു നിവേദനം: അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ, ഞാൻ നുഅ്മാന് ഒരു വസ്തു ഭാഗിച്ചു നൽകിയിട്ടുണ്ട്? നബി(സ) ചോദിച്ചു: "അവന്റെ സഹോദരങ്ങൾക്ക് നീ നൽകിയോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "എങ്കിൽ അത് തിരിച്ചു വാങ്ങുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أُمَّهُ ابْنَةَ رَوَاحَةَ سَأَلَتْ أَبَاهُ بَعْضَ الْمَوْهِبَةِ مِنْ مَالِهِ لِابْنِهَا، فَالْتَوَى بِهَا سَنَةً، ثُمَّ بَدَا لَهُ فَوَهَبَهَا لَهُ، فَقَالَتْ: لَا أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللهِ، إِنَّ أُمَّ هَذَا ابْنَةَ رَوَاحَةَ قَاتَلَتْنِي عَلَى الَّذِي وَهَبْتُ لَهُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا بَشِيرُ، أَلَكَ وَلَدٌ سِوَى – ابْنُ غَيْرُ – هَذَا". قَالَ: نَعَمْ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَفَكُلَّهُمْ وَهَبْتَ لَهُمْ مِثْلَ الَّذِي وَهَبْتَ لِابْنِكَ هَذَا". قَالَ: لَا. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَلَا تُشْهِدْنِي إِذًا، فَإِنِّي لَا أَشْهَدُ عَلَى جَوْرٍ". وَفِي رِوَايَةٍ: "أَلَا سَوَّيْتَ بَيْنَهُمْ". (ن)', 'നുഅ്മാനുബ്നു ബശീറുൽ അൻസ്വാരി(റ): അദ്ദേഹത്തിന്റെ മാതാവ് ബിൻതുറവാഹ(റ) തന്റെ പിതാവിനോട് തന്റെ മുതലിൽനിന്ന് അൽപം തന്റെ മകന് നൽകാൻ ആവശ്യപ്പെട്ടു. എന്നാൽ അദ്ദേഹം ഒരു വർഷം അക്കാര്യം പിന്തിപ്പിക്കുകയും ശേഷം നൽകണമെന്ന് തോന്നിയപ്പോൾ അത് അവന് നൽകുകയും ചെയ്തു. അപ്പോൾ ബിൻതുറവാഹ(റ) പറഞ്ഞു: (ഇക്കാര്യത്തിന്) റസൂൽ(സ)യെ സാക്ഷി നിർത്താതെ ഞാൻ തൃപ്തയാവുകയില്ല. അങ്ങനെ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇവനു ഞാൻ നൽകിയ വിഷയത്തിൽ ഇവന്റെ ഉമ്മ ബിൻതുറവാഹ എന്നോട് കലഹിച്ചിരിക്കുന്നു. റസൂൽ(സ) ചോദിച്ചു: "ബശീറേ, നിനക്ക് ഇവനല്ലാത്ത സന്താനങ്ങൾ - ആൺകുട്ടികൾ - ഉണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ ഈ മകന് നൽകിയതുപോലെ അവർക്കെല്ലാം നീ നൽകിയിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ നീ എന്നെ സാക്ഷി നിർത്തരുത്. നിശ്ചയം ഞാൻ അനീതിക്ക് സാക്ഷി നിൽക്കുകയില്ല." മറ്റൊരു നിവേദനം: "അവർക്കിടയിൽ നീ തുല്ല്യമായി ഭാഗിച്ചുകൂടായിരുന്നോ" (ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ الْأَنْصَارِيِّ', 'നുഅ്മാനുബ്നു ബശീറുൽ അൻസ്വാരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 871, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=42), 1, 'وَفِي رِوَايَةٍ: "أَلَا سَوَّيْتَ بَيْنَهُمْ". (ن)', 'മറ്റൊരു നിവേദനം: "അവർക്കിടയിൽ നീ തുല്ല്യമായി ഭാഗിച്ചുകൂടായിരുന്നോ" (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اعْدِلُوا بَيْنَ أَبْنَائِكُمْ، اعْدِلُوا بَيْنَ أَبْنَائِكُمْ". (ن)', 'നുഅ്മാനുബ്നു ബശീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ സന്താനങ്ങൾക്കിടയിൽ നിങ്ങൾ നീതി പാലിക്കുക, നിങ്ങളുടെ സന്താനങ്ങൾക്കിടയിൽ നിങ്ങൾ നീതി പാലിക്കുക." (ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 872, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: تَصَدَّقَ عَلَيَّ أَبِي بِبَعْضِ مَالِهِ، فَقَالَتْ أُمِّي عَمْرَةُ بِنْتُ رَوَاحَةَ: لَا أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَانْطَلَقَ أَبِي إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِيُشْهِدَهُ عَلَى صَدَقَتِي، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَفَعَلْتَ هَذَا بِوَلَدِكَ كُلِّهِمْ". قَالَ: لَا، قَالَ: "اتَّقُوا اللهَ، وَاعْدِلُوا فِي أَوْلَادِكُمْ". فَرَجَعَ أَبِي، فَرَدَّ تِلْكَ الصَّدَقَةَ. (م)', 'നുഅ്മാനുബ്നു ബശീർ(റ): എന്റെ പിതാവ് തന്റെ മുതലിൽനിന്ന് അൽപം എനിക്ക് ദാനമായി നൽകി. അപ്പോൾ എന്റെ ഉമ്മ അംറതു ബിൻതുറവാഹ(റ) പറഞ്ഞു: (ഇക്കാര്യത്തിൽ) റസൂൽ(സ)യെ താങ്കൾ സാക്ഷി നിർത്തുംവരെ ഞാൻ തൃപ്തയാവുകയില്ല. അങ്ങനെ എനിക്കു നൽകിയ ദാനത്തിന് നബി(സ)യെ സാക്ഷി നിർത്തുന്നതിനു വേണ്ടി എന്റെ പിതാവ് എന്നെയും കൂട്ടി തിരുമേനി(സ)യുടെ അടുത്ത് പോയി. അപ്പോൾ റസൂൽ(സ) പിതാവിനോട് ചോദിച്ചു: "നിന്റെ സന്താനങ്ങൾക്കെല്ലാം നീ ഇപ്രകാരം ചെയ്തിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുകയും നിങ്ങളുടെ സന്താനങ്ങൾക്കിടയിൽ നീതി പാലിക്കുകയും ചെയ്യുക." അങ്ങനെ എന്റെ പിതാവ് മടങ്ങുകയും ആ ദാനം തിരിച്ചുവാങ്ങുകയും ചെയ്തു. (മു)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 872, 872, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَعْطَانِي أَبِي عَطِيَّةً، فَقَالَتْ عَمْرَةُ بِنْتُ رَوَاحَةَ: لَا أَرْضَى حَتَّى تُشْهِدَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي أَعْطَيْتُ ابْنِي مِنْ عَمْرَةَ بِنْتِ رَوَاحَةَ عَطِيَّةً، فَأَمَرَتْنِي أَنْ أُشْهِدَكَ يَا رَسُولَ اللهِ، قَالَ: "أَعْطَيْتَ سَائِرَ وَلَدِكَ مِثْلَ هَذَا؟" قَالَ: لَا. قَالَ: "فَاتَّقُوا اللهَ، وَاعْدِلُوا بَيْنَ أَوْلَادِكُمْ". قَالَ: فَرَجَعَ، فَرَدَّ عَطِيَّتَهُ. (خ)', 'നുഅ്മാനുബ്നു ബശീർ(റ): എന്റെ പിതാവ് എനിക്ക് ചില മുതലുകൾ നൽകി. അപ്പോൾ അംറതു ബിൻതുറവാഹ(റ) പറഞ്ഞു: (ഇക്കാര്യത്തിൽ) റസൂൽ(സ)യെ സാക്ഷി നിർത്താതെ ഞാൻ തൃപ്തയാവുകയില്ല. അങ്ങനെ അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അംറതു ബിൻതുറവാഹയിലുള്ള എന്റെ മകന്. നിശ്ചയം ഞാൻ ചില മുതലുകൾ നൽകുകയും (അക്കാര്യത്തിൽ) അങ്ങയെ സാക്ഷി നിർത്തണമെന്ന് അവൾ എന്നോട് ആവശ്യപ്പെടുകയും ചെയ്തിരിക്കുന്നു, അല്ലാഹുവിന്റെ റസൂലേ. തിരുമേനി(സ) പറഞ്ഞു: "ഇപ്രകാരം നിന്റെ മറ്റു സന്താനങ്ങൾക്കും നീ നൽകിയിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "എങ്കിൽ അല്ലാഹുവിനെ നിങ്ങൾ സൂക്ഷിക്കുകയും നിങ്ങളുടെ സന്താനങ്ങൾക്കിടയിൽ നീതി പാലിക്കുകയും ചെയ്യുക." നിവേദകൻ പറഞ്ഞു: അങ്ങനെ അദ്ദേഹം മടങ്ങുകയും ആ ദാനം തിരിച്ചു വാങ്ങുകയും ചെയ്തു. (ബു)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 872, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَنْحَلَنِي أَبِي نُحْلًا – وَفِي رِوَايَةٍ: نَحْلَةً – غُلَامًا لَهُ، قَالَ: فَقَالَتْ لَهُ أُمِّي عَمْرَةُ بِنْتُ رَوَاحَةَ: ائْتِ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَشْهِدْهُ، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَشْهَدَهُ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ لَهُ: إِنِّي نَحَلْتُ ابْنِي النُّعْمَانَ نُحْلًا، وَإِنَّ عَمْرَةَ سَأَلَتْنِي أَنْ أُشْهِدَكَ عَلَى ذَلِكَ؟ قَالَ: فَقَالَ: "أَلَكَ وَلَدٌ سِوَاهُ". قَالَ: قُلْتُ: نَعَمْ قَالَ: "فَكُلَّهُمْ أَعْطَيْتَ مِثْلَ مَا أَعْطَيْتَ النُّعْمَانَ". قَالَ: لَا. قَالَ: "هَذَا جَوْرٌ". وَفِي رِوَايَةٍ: "هَذَا تَلْجِئَةٌ، فَأَشْهِدْ عَلَى هَذَا غَيْرِي". وَفِي رِوَايَةٍ قَالَ: "أَلَيْسَ يَسُرُّكَ أَنْ يَكُونُوا لَكَ فِي الْبِرِّ وَاللُّطْفِ سَوَاءً". قَالَ: نَعَمْ، قَالَ: "فَأَشْهِدْ عَلَى هَذَا غَيْرِي". وَفِي رِوَايَةٍ: "إِنَّ لَهُمْ عَلَيْكَ مِنَ الْحَقِّ أَنْ تَعْدِلَ بَيْنَهُمْ، كَمَا أَنَّ لَكَ عَلَيْهِمْ مِنَ الْحَقِّ أَنْ يَبِرُّوكَ". وَفِي رِوَايَاتٍ: "أَكُلَّ بَنِيكَ". "وَلَدَكَ". "أَلَكَ بَنُونَ سِوَاهُ". "أَلَكَ وَلَدٌ غَيْرُهُ". (ق,د,ت,ن,جه)', 'നുഅ്മാനുബ്നു ബശീർ(റ): എന്റെ പിതാവ് എനിക്ക് ഒരു അടിമയെ ''നുഹ്ൽ'' ആയി നൽകി. അപ്പോൾ എന്റെ ഉമ്മ അംറതു ബിൻതുറവാഹ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: താങ്കൾ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് തിരുമേനിയെ (ഇക്കാര്യത്തിന്) സാക്ഷി നിർത്തുക. അങ്ങനെ അദ്ദേഹം നബി(സ)യുടെ അടുത്ത് ചെന്ന് തിരുമേനി(സ)യെ സാക്ഷി നിർത്തുകയും അവിടുത്തോട് കാര്യങ്ങൾ പറയുകയും ചെയ്തു. അദ്ദേഹം തിരുമേനി(സ)യോട് പറഞ്ഞു: എന്റെ മകൻ നുഅ്മാന് നിശ്ചയം ഞാൻ ഒരു മുതൽ നൽകി. അങ്ങനെ അക്കാര്യത്തിൽ അങ്ങയെ സാക്ഷി നിർത്തണമെന്ന് അംറ എന്നോട് ആവശ്യപ്പെട്ടിരിക്കുന്നു? നിവേദകൻ പറയുന്നു: റസൂൽ(സ) ചോദിച്ചു: "നിനക്ക് അവനല്ലാതെ സന്താനങ്ങളുണ്ടോ?" അദ്ദേഹം പറയുന്നു: ഞാൻ പറഞ്ഞു: അതെ. അവിടുന്ന് ചോദിച്ചു: "നുഅ്മാന് നൽകിയതു പോലെ അവർക്കെല്ലാം നീ നൽകിയിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "ഇത് അനീതിയാണ്." മറ്റൊരു നിവേദനം: "ഇത് അക്രമമാണ്, അതിനാൽ ഞാനല്ലാതെ മറ്റാരെയെങ്കിലും ഇതിന് സാക്ഷി നിർത്തുക." മറ്റൊരു നിവേദനം: "നിനക്ക് ഗുണവും കാരുണ്യവും ചെയ്യുന്നതിൽ അവരെല്ലാം (സന്താനങ്ങൾ) സമന്മാരാകണം എന്ന് നീ ആഗ്രഹിക്കുന്നില്ലേ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ മറ്റാരെയെങ്കിലും ഇതിന് സാക്ഷി നിർത്തുക." മറ്റൊരു നിവേദനം: "നിനക്ക് ഗുണംചെയ്യണമെന്നത് അവർക്ക് നിന്നോടുള്ള കടമയാണ് എന്നതുപോലെ, നീ അവർക്കിടയിൽ നീതി ചെയ്യണമെന്നത് നിനക്ക് അവരോടുള്ള കടമയാണ്." മറ്റു നിവേദനങ്ങളിൽ ഇപ്രകാരമെല്ലാം വന്നിട്ടുണ്ട്: "നിന്റെ ആൺകുട്ടികൾക്കെല്ലാം (നീ നൽകിയോ)", "നിന്റെ സന്താനങ്ങൾക്കെല്ലാം (നൽകിയോ)", "നിനക്ക് അവനല്ലാത്ത ആൺമക്കളുണ്ടോ?", "നിനക്ക് അവനൊഴികെ സന്താനങ്ങളുണ്ടോ?" (ബു,മു,ദ,തു,ന,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 873, 873, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=46), 1, 'وَفِي رِوَايَةٍ: نَحْلَةً – غُلَامًا لَهُ، قَالَ: فَقَالَتْ لَهُ أُمِّي عَمْرَةُ بِنْتُ رَوَاحَةَ: ائْتِ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَشْهِدْهُ، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَشْهَدَهُ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ لَهُ: إِنِّي نَحَلْتُ ابْنِي النُّعْمَانَ نُحْلًا، وَإِنَّ عَمْرَةَ سَأَلَتْنِي أَنْ أُشْهِدَكَ عَلَى ذَلِكَ؟ قَالَ: فَقَالَ: "أَلَكَ وَلَدٌ سِوَاهُ". قَالَ: قُلْتُ: نَعَمْ قَالَ: "فَكُلَّهُمْ أَعْطَيْتَ مِثْلَ مَا أَعْطَيْتَ النُّعْمَانَ". قَالَ: لَا. قَالَ: "هَذَا جَوْرٌ".', 'മറ്റൊരു നിവേദനം: "ഇത് അക്രമമാണ്, അതിനാൽ ഞാനല്ലാതെ മറ്റാരെയെങ്കിലും ഇതിന് സാക്ഷി നിർത്തുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=46), 2, 'وَفِي رِوَايَةٍ: "هَذَا تَلْجِئَةٌ، فَأَشْهِدْ عَلَى هَذَا غَيْرِي".', 'മറ്റൊരു നിവേദനം: "നിനക്ക് ഗുണവും കാരുണ്യവും ചെയ്യുന്നതിൽ അവരെല്ലാം (സന്താനങ്ങൾ) സമന്മാരാകണം എന്ന് നീ ആഗ്രഹിക്കുന്നില്ലേ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ മറ്റാരെയെങ്കിലും ഇതിന് സാക്ഷി നിർത്തുക."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=46), 3, 'وَفِي رِوَايَةٍ قَالَ: "أَلَيْسَ يَسُرُّكَ أَنْ يَكُونُوا لَكَ فِي الْبِرِّ وَاللُّطْفِ سَوَاءً". قَالَ: نَعَمْ، قَالَ: "فَأَشْهِدْ عَلَى هَذَا غَيْرِي".', 'മറ്റൊരു നിവേദനം: "നിനക്ക് ഗുണംചെയ്യണമെന്നത് അവർക്ക് നിന്നോടുള്ള കടമയാണ് എന്നതുപോലെ, നീ അവർക്കിടയിൽ നീതി ചെയ്യണമെന്നത് നിനക്ക് അവരോടുള്ള കടമയാണ്." മറ്റു നിവേദനങ്ങളിൽ ഇപ്രകാരമെല്ലാം വന്നിട്ടുണ്ട്: "നിന്റെ ആൺകുട്ടികൾക്കെല്ലാം (നീ നൽകിയോ)", "നിന്റെ സന്താനങ്ങൾക്കെല്ലാം (നൽകിയോ)", "നിനക്ക് അവനല്ലാത്ത ആൺമക്കളുണ്ടോ?", "നിനക്ക് അവനൊഴികെ സന്താനങ്ങളുണ്ടോ?" (ബു,മു,ദ,തു,ന,ജ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=46), 4, 'وَفِي رِوَايَةٍ: "إِنَّ لَهُمْ عَلَيْكَ مِنَ الْحَقِّ أَنْ تَعْدِلَ بَيْنَهُمْ، كَمَا أَنَّ لَكَ عَلَيْهِمْ مِنَ الْحَقِّ أَنْ يَبِرُّوكَ". وَفِي رِوَايَاتٍ: "أَكُلَّ بَنِيكَ". "وَلَدَكَ". "أَلَكَ بَنُونَ سِوَاهُ". "أَلَكَ وَلَدٌ غَيْرُهُ". (ق,د,ت,ن,جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَعْطَاهُ أَبُوهُ غُلَامًا، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا هَذَا الْغُلَامُ؟" قَالَ: غُلَامِي أَعْطَانِيهِ أَبِي، قَالَ: "فَكُلَّ إِخْوَتِكَ أَعْطَى كَمَا أَعْطَاكَ؟" قَالَ: لَا، قَالَ: "فَارْدُدْهُ". (م,د,ن)', 'നുഅ്മാനുബ്നു ബശീർ(റ): അദ്ദേഹത്തിന്റെ പിതാവ് അദ്ദേഹത്തിന് ഒരു അടിമയെ നൽകി. അങ്ങനെ റസൂൽ(സ) അദ്ദേഹത്തോട് ചോദിച്ചു: "ഏതാണ് ഈ അടിമ?" അദ്ദേഹം പറഞ്ഞു: എന്റെ പിതാവ് നൽകിയ അടിമയാണ്. റസൂൽ(സ) ചോദിച്ചു: "നിനക്കു നൽകിയതുപോലെ അദ്ദേഹം നിന്റെ സഹോദരങ്ങൾക്കെല്ലാം നൽകിയിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ അവനെ തിരിച്ചു നൽകുക." (മു,ദ,ന)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 873, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَتِ امْرَأَةُ بَشِيرٍ: انْحَلِ ابْنِي غُلَامَكَ، وَأَشْهِدْ لِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ ابْنَةَ فُلَانٍ سَأَلَتْنِي أَنْ أَنْحَلَ ابْنَهَا غُلَامًا، وَقَالَتْ لِي: أَشْهِدْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "لَهُ إِخْوَةٌ". فَقَالَ: نَعَمْ، قَالَ: "فَكُلَّهُمْ أَعْطَيْتَ مِثْلَ مَا أَعْطَيْتَهُ". قَالَ: لَا، قَالَ: "فَلَيْسَ يَصْلُحُ هَذَا، وَإِنِّي لَا أَشْهَدُ إِلَّا عَلَى حَقٍّ". (م,د)', 'ജാബിർ(റ): ബശീർ(റ)വിന്റെ ഭാര്യ പറഞ്ഞു: എന്റെ മകന് താങ്കളുടെ അടിമയെ നൽകുകയും റസൂൽ(സ)യെ എനിക്ക് (അക്കാര്യത്തിൽ) സാക്ഷി നിർത്തുകയും ചെയ്യുക. അങ്ങനെ അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: നിശ്ചയം ഇന്നയാളുടെ മകൾ (എന്റെ ഭാര്യ) അവളുടെ മകന് ഒരു അടിമയെ നൽകണമെന്ന് എന്നോട് ആവശ്യപ്പെടുകയും എന്നോട് ഇപ്രകാരം പറയുകയും ചെയ്തു: (അക്കാര്യത്തിൽ) താങ്കൾ റസൂൽ(സ)യെ സാക്ഷി നിർത്തുക. റസൂൽ(സ) പറഞ്ഞു: "അവന് സഹോദരങ്ങളുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ. റസൂൽ(സ) ചോദിച്ചു: "അവന് നൽകിയതുപോലെ നീ അവർക്കെല്ലാം നൽകിയിട്ടുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "അത് ശരിയാവുകയില്ല. നിശ്ചയം സത്യത്തിനല്ലാതെ ഞാൻ സാക്ഷി നിൽക്കുകയില്ല." (മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْعُمْرَى هِيَ لِلْوَارِثِ". وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْعُمْرَى لِلْوَارِثِ. (ن)', 'സൈദുബ്നു സാബിത്(റ): നബി(സ) പറഞ്ഞു: "ഉംറാ മുതൽ അനന്തരാവകാശിക്കുള്ളതാണ്." മറ്റൊരു നിവേദനം: നിശ്ചയം ഉംറാ മുതൽ അനന്തരാവകാശിക്കുള്ളതാണെന്ന് നബി(സ) വിധിച്ചു. (ന)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=49), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْعُمْرَى لِلْوَارِثِ. (ن)', 'മറ്റൊരു നിവേദനം: നിശ്ചയം ഉംറാ മുതൽ അനന്തരാവകാശിക്കുള്ളതാണെന്ന് നബി(സ) വിധിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُعْمِرَ شَيْئًا فَهُوَ لِمُعْمَرِهِ، مَحْيَاهُ وَمَمَاتَهُ. وَلَا تُرْقِبُوا، فَمَنْ أُرْقِبَ شَيْئًا فَهُوَ لِسَبِيلِهِ". (ن)', 'സൈദുബ്നു സാബിത്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും വല്ലതും ഉംറാ മുതലായി നൽകിയാൽ അത് തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും അപ്രകാരം നൽകപ്പെട്ടവനുള്ളതാണ്. നിങ്ങൾ മരണ ശേഷം തിരിച്ചു ലഭിക്കണമെന്ന രീതിയിൽ ഭൂമി നൽകരുത് (റുഖ്ബാ). ആരെങ്കിലും റുഖ്ബാ നൽകിയാൽ അത് അതിന്റേതായ മാർഗ്ഗത്തിലായിരിക്കും." (ന)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 874, 874, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ طَاوُسٍ قَالَ: بَتَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعُمْرَى وَالرُّقْبَى. (ن)', 'ത്വാഊസ്(റ): ഉംറാ ദാനത്തെയും റുഖ്ബാ ദാനത്തെയും റസൂൽ(സ) നടപ്പിലാക്കി (ദാനം നൽകിയവന് തിരിച്ചു ലഭിക്കാത്ത രീതിയിൽ). (ന)', 'طَاوُسٍ قَالَ', 'ത്വാഊസ്(റ)', '³. ഒരാൾക്ക് തന്റെ ആയുസ്സ്കാലംവരെ ഭൂമി ദാനം നൽകലാണ് ''ഉംറാ'' ദാനം.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَطَاءٍ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْعُمْرَى وَالرُّقْبَى. وَفِي رِوَايَةٍ: قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُعْطِيَ شَيْئًا حَيَاتَهُ فَهُوَ لَهُ حَيَاتَهُ وَمَوْتَهُ". (ن)', 'അത്വാഅ്(റ): ഉംറാ ദാനത്തെയും റുഖ്ബാ ദാനത്തെയും റസൂൽ(സ) നിരോധിച്ചു. മറ്റൊരു നിവേദനം: "ഒരാളുടെ ജീവിതകാലത്തേക്കായി വല്ലതും നൽകപ്പെട്ടാൽ, തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും അത് അവനുള്ളത് തന്നെയാണ്." (ന)', 'عَطَاءٍ قَالَ', 'അത്വാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 874, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=52), 1, 'وَفِي رِوَايَةٍ: قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُعْطِيَ شَيْئًا حَيَاتَهُ فَهُوَ لَهُ حَيَاتَهُ وَمَوْتَهُ". (ن)', 'മറ്റൊരു നിവേദനം: "ഒരാളുടെ ജീവിതകാലത്തേക്കായി വല്ലതും നൽകപ്പെട്ടാൽ, തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും അത് അവനുള്ളത് തന്നെയാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُرْقِبُوا وَلَا تُعْمِرُوا، فَمَنْ أُرْقِبَ أَوْ أُعْمِرَ شَيْئًا فَهُوَ لِوَرَثَتِهِ". (ن)', 'ജാബിർ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഉംറാ ദാനവും റുഖ്ബാ ദാനവും നൽകരുത്. ആർക്കെങ്കിലും ഉംറാ ദാനമോ റുഖ്ബാ ദാനമോ നൽകപ്പെട്ടാൽ അത് അവന്റെ അനന്തരാവകാശികൾക്കുള്ളതാണ്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا عُمْرَى وَلَا رُقْبَى، فَمَنْ أُعْمِرَ شَيْئًا أَوْ أُرْقِبَهُ فَهُوَ لَهُ حَيَاتَهُ وَمَمَاتَهُ". (ن,جه)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഉംറാ ദാനമോ റുഖ്ബാ ദാനമോ പാടില്ല. ആർക്കെങ്കിലും ഉംറാ ദാനമോ റുഖ്ബാ ദാനമോ നൽകപ്പെട്ടാൽ അത് തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും അവനു തന്നെയുള്ളതാണ്." (ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا مَعْشَرَ الْأَنْصَارِ، أَمْسِكُوا عَلَيْكُمْ – يَعْنِي – أَمْوَالَكُمْ، لَا تُعْمِرُوهَا، فَإِنَّهُ مَنْ أُعْمِرَ شَيْئًا فَإِنَّهُ لِمَنْ أُعْمِرَهُ حَيَاتَهُ وَمَمَاتَهُ". وَفِي رِوَايَةٍ: قَالَ: "أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلَا تُعْمِرُوهَا، فَمَنْ أُعْمِرَ شَيْئًا حَيَاتَهُ فَهُوَ لَهُ حَيَاتَهُ وَبَعْدَ مَوْتِهِ". (ن)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അൻസ്വാരീ സമൂഹമേ, നിങ്ങളുടെ മുതലുകളെ നിങ്ങൾ സൂക്ഷിച്ചു വെക്കുക. അതിനെ നിങ്ങൾ ഉംറാ ദാനമായി നൽകരുത്. നിശ്ചയം ആരെങ്കിലും വല്ലതും ഉംറാ ദാനമായി നൽകിയാൽ, തന്റെ ജീവിതകാലത്തും മരണ ശേഷവും അത് ഉംറാ ദാനമായി നൽകപ്പെട്ട വ്യക്തിക്കുള്ളതാണ്." മറ്റൊരു നിവേദനം: തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളുടെ മുതലുകളെ നിങ്ങൾ സൂക്ഷിച്ചു വെക്കുക, അവയെ ഉംറാ ദാനമായി നൽകരുത്. ആർക്കെങ്കിലും തന്റെ ജീവിതകാലത്ത് വല്ലതും ഉംറാ ദാനമായി നൽകപ്പെട്ടാൽ, തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും അതു അവനു തന്നെയുള്ളതാണ്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=55), 1, 'وَفِي رِوَايَةٍ: قَالَ: "أَمْسِكُوا عَلَيْكُمْ أَمْوَالَكُمْ وَلَا تُعْمِرُوهَا، فَمَنْ أُعْمِرَ شَيْئًا حَيَاتَهُ فَهُوَ لَهُ حَيَاتَهُ وَبَعْدَ مَوْتِهِ". (ن)', 'മറ്റൊരു നിവേദനം: തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങളുടെ മുതലുകളെ നിങ്ങൾ സൂക്ഷിച്ചു വെക്കുക, അവയെ ഉംറാ ദാനമായി നൽകരുത്. ആർക്കെങ്കിലും തന്റെ ജീവിതകാലത്ത് വല്ലതും ഉംറാ ദാനമായി നൽകപ്പെട്ടാൽ, തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും അതു അവനു തന്നെയുള്ളതാണ്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا رَجُلٍ أَعْمَرَ رَجُلًا عُمْرَى لَهُ وَلِعَقِبِهِ، فَهِيَ لَهُ وَلِمَنْ يَرِثُهُ مِنْ عَقِبِهِ مَوْرُوثَةً". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഏതെങ്കിലുമൊരാൾ മറ്റൊരാൾക്കും അവന്റെ സന്താനങ്ങൾക്കും ഉംറാ ദാനം നൽകിയാൽ, അത് അവനും തന്റെ സന്താനങ്ങളിൽനിന്ന് തന്നെ അനന്തരമെടുക്കുന്നവർക്കും ഉള്ളതാണ്." (ദ,ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 875, 875, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ أَعْمَرَ رَجُلًا عُمْرَى، لَهُ وَلِعَقِبِهِ، فَقَدْ قَطَعَ قَوْلُهُ حَقَّهُ، وَهِيَ لِمَنْ أُعْمِرَ وَلِعَقِبِهِ". وَفِي رِوَايَةٍ قَالَ: "أَيُّمَا رَجُلٍ أَعْمَرَ عُمْرَى، لَهُ وَلِعَقِبِهِ، فَإِنَّهَا لِلَّذِي يُعْطَاهَا، لَا تَرْجِعُ إِلَى الَّذِي أَعْطَاهَا، لِأَنَّهُ أَعْطَى عَطَاءً وَقَعَتْ فِيهِ الْمَوَارِيثُ". (م,د,ت,ن,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും ഒരാൾക്കും അവന്റെ സന്താനങ്ങൾക്കും വല്ലതും ഉംറാ ദാനമായി നൽകിയാൽ, അവന്റെ വാക്ക് അവന്റെ അവകാശത്തെ അവസാനിപ്പിച്ചിരിക്കുന്നു. ആ മുതൽ ഉംറാ ദാനമായി നൽകപ്പെട്ടവനും അവന്റെ സന്താനങ്ങൾക്കുമുള്ളതാണ്." മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "ഏതെങ്കിലും ഒരു വ്യക്തിക്കും അവന്റെ സന്താനങ്ങൾക്കും വല്ലതും ഉംറാ ദാനമായി നൽകപ്പെട്ടാൽ, നൽകപ്പെടുന്ന വ്യക്തിക്ക് അവകാശപ്പെട്ടതാണ് അത്. നൽകിയ വ്യക്തിയിലേക്ക് അത് മടങ്ങുകയില്ല. കാരണം അനന്തര വിഹിതം സംഭവിക്കുന്ന ഒരു ദാനമാണ് അവൻ നൽകിയിട്ടുള്ളത്." (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 875, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=57), 1, 'وَفِي رِوَايَةٍ قَالَ: "أَيُّمَا رَجُلٍ أَعْمَرَ عُمْرَى، لَهُ وَلِعَقِبِهِ، فَإِنَّهَا لِلَّذِي يُعْطَاهَا، لَا تَرْجِعُ إِلَى الَّذِي أَعْطَاهَا، لِأَنَّهُ أَعْطَى عَطَاءً وَقَعَتْ فِيهِ الْمَوَارِيثُ". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "ഏതെങ്കിലും ഒരു വ്യക്തിക്കും അവന്റെ സന്താനങ്ങൾക്കും വല്ലതും ഉംറാ ദാനമായി നൽകപ്പെട്ടാൽ, നൽകപ്പെടുന്ന വ്യക്തിക്ക് അവകാശപ്പെട്ടതാണ് അത്. നൽകിയ വ്യക്തിയിലേക്ക് അത് മടങ്ങുകയില്ല. കാരണം അനന്തര വിഹിതം സംഭവിക്കുന്ന ഒരു ദാനമാണ് അവൻ നൽകിയിട്ടുള്ളത്." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى: أَنَّهُ مَنْ أَعْمَرَ رَجُلًا عُمْرَى لَهُ وَلِعَقِبِهِ، فَإِنَّهَا لِلَّذِي أُعْمِرَهَا، يَرِثُهَا مِنْ صَاحِبِهَا الَّذِي أَعْطَاهَا مَا وَقَعَ مِنْ مَوَارِيثِ اللهِ وَحَقِّهِ. (ن)', 'ജാബിർ(റ): നിശ്ചയം റസൂൽ(സ) ഇപ്രകാരം വിധിച്ചു: നിശ്ചയം ആരെങ്കിലും ഒരു വ്യക്തിക്കും അവന്റെ സന്താനങ്ങൾക്കും വല്ലതും ഉംറാ ദാനമായി നൽകിയാൽ, ദാനം നൽകപ്പെട്ട വ്യക്തിക്കുള്ളതാണ് അത്. അല്ലാഹുവിന്റെ നിയമത്തിലെ അനന്തരവിഹിതവും അവകാശവും അനുസരിച്ച് അതു നൽകിയ വ്യക്തിയിൽനിന്ന് അവൻ അതിനെ അനന്തരമെടുക്കും. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى فِيمَنْ أُعْمِرَ عُمْرَى لَهُ وَلِعَقِبِهِ، فَهِيَ لَهُ بَتْلَةً، لَا يَجُوزُ لِلْمُعْطِي مِنْهَا شَرْطٌ وَلَا ثُنْيَا. قَالَ أَبُو سَلَمَةَ: لِأَنَّهُ أَعْطَى عَطَاءً وَقَعَتْ فِيهِ الْمَوَارِيثُ، فَقَطَعَتِ الْمَوَارِيثُ شَرْطَهُ. (ن)', 'ജാബിർ(റ): ഏതെങ്കിലും ഒരു വ്യക്തിക്കും അവന്റെ സന്താനങ്ങൾക്കും വല്ലതും ഉംറാ ദാനമായി നൽകപ്പെട്ടാൽ, ദാനം നൽകിയവന് ഒന്നും ലഭിക്കാത്ത വിധം അത് അവനുതന്നെ അവകാശപ്പെട്ടതാണെന്ന് റസൂൽ(സ) വിധിച്ചിരിക്കുന്നു. ദാനം നൽകിയവന് അതിൽ വല്ല നിബന്ധനയോ ഒഴിവോ വെക്കൽ അനുവദനീയമല്ല. അബൂസലമ(റ) പറയുന്നു: കാരണം, അനന്തരവിഹിതം സംഭവിക്കുന്ന ഒരു ദാനമായാണ് അവൻ നൽകിയിരിക്കുന്നത്. അതിനാൽ അനന്തരവിഹിതം അവന്റെ നിബന്ധനയെ ഇല്ലാതാക്കിയിരിക്കുന്നു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا رَجُلٍ أَعْمَرَ رَجُلًا عُمْرَى لَهُ وَلِعَقِبِهِ، قَالَ: قَدْ أَعْطَيْتُكَهَا وَعَقِبَكَ مَا بَقِيَ مِنْكُمْ أَحَدٌ. فَإِنَّهَا لِمَنْ أُعْطِيَهَا، وَإِنَّهَا لَا تَرْجِعُ إِلَى صَاحِبِهَا، مِنْ أَجْلِ أَنَّهُ أَعْطَاهَا عَطَاءً وَقَعَتْ فِيهِ الْمَوَارِيثُ". (ن)', 'ജാബിർ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഏതെങ്കിലുമൊരാൾ ഒരു വ്യക്തിക്കും അവന്റെ സന്താനങ്ങൾക്കും വല്ല ഉംറാ ദാനവും നൽകുകയും ''നിങ്ങളിൽ ഒരുത്തൻ ശേഷിക്കുന്ന കാലംവരെ ഇതിനെ നിനക്കും നിന്റെ സന്താനങ്ങൾക്കും ഞാൻ നൽകിയിരിക്കുന്നു'' എന്ന് പറയുകയും ചെയ്താൽ, നൽകപ്പെട്ട വ്യക്തിക്ക് അവകാശപ്പെട്ടതാണത്. നിശ്ചയം അതിന്റെ ഉടമക്ക് അത് തിരിച്ചു ലഭിക്കുകയില്ല. കാരണം, അനന്തരവിഹിതം സംഭവിക്കുന്ന ദാനമായിട്ടാണ് അവൻ അത് നൽകിയിട്ടുള്ളത്." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَضَى بِالْعُمْرَى: أَنْ يَهَبَ الرَّجُلُ لِلرَّجُلِ وَلِعَقِبِهِ الْهِبَةَ، وَيَسْتَثْنِي: إِنْ حَدَثَ بِكَ حَدَثٌ وَبِعَقِبِكَ فَهُوَ إِلَيَّ وَإِلَى عَقِبِي: إِنَّهَا لِمَنْ أُعْطِيَهَا وَلِعَقِبِهِ. (ن)', 'ജാബിർ(റ): നിശ്ചയം റസൂൽ(സ) ഇപ്രകാരം വിധിച്ചു: ഒരാൾ മറ്റൊരാൾക്കും അവന്റെ സന്താനങ്ങൾക്കും ഒരു ദാനം നൽകുകയും, നിനക്കും നിന്റെ സന്താനങ്ങൾക്കും വല്ലതും സംഭവിച്ചാൽ അത് എനിക്കും എന്റെ സന്താനങ്ങൾക്കും അവകാശപ്പെട്ടതായിരിക്കും എന്ന് അവൻ ഒഴിവു പറയുകയും ചെയ്താൽ, നിശ്ചയം അത് നൽകപ്പെട്ടവനും അവന്റെ സന്താനങ്ങൾക്കും അവകാശപ്പെട്ടതാണ്. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "الْعُمْرَى لِمَنْ وُهِبَتْ لَهُ". (ق,د,ن)', 'ജാബിർ(റ): നിശ്ചയം നബി(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "ഉംറാ ദാനം അത് നൽകപ്പെട്ടവനുള്ളതാണ്." (ബു,മു,ദ,ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 876, 876, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّمَا الْعُمْرَى الَّتِي أَجَازَهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَقُولَ: هِيَ لَكَ وَلِعَقِبِكَ، فَأَمَّا إِذَا قَالَ: هِيَ لَكَ مَا عِشْتَ، فَإِنَّهَا تَرْجِعُ إِلَى صَاحِبِهَا. (م,د)', 'ജാബിർ(റ): റസൂൽ(സ) നടപ്പിൽ വരുത്തിയ (ഉടമയ്ക്ക് തിരിച്ചു ലഭിക്കാത്ത) ഉംറാ ദാനം ''അത് നിനക്കും നിന്റെ സന്താനങ്ങൾക്കുമുള്ളതാണ്'' എന്ന് പറയുന്ന ദാനമാണ്. ''നീ ജീവിച്ചിരിക്കുന്ന കാലത്തോളം അത് നിനക്കുള്ളതാണ്'' എന്നാണ് പറഞ്ഞിട്ടുള്ളതെങ്കിൽ, നിശ്ചയം അത് അതിന്റെ ഉടമക്കുതന്നെ തിരിച്ചു ലഭിക്കുന്നതാണ്. (മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَعَلَ الْعُمْرَى لِلْوَارِثِ. (د,ن,جه)', 'സൈദുബ്നു സാബിത്(റ): നിശ്ചയം റസൂൽ(സ) ഉംറാ ദാനത്തെ അനന്തരാവകാശികൾക്ക് നിശ്ചയിച്ചു കൊടുത്തു. (ദ,ന,ജ)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي امْرَأَةٍ مِنَ الْأَنْصَارِ أَعْطَاهَا ابْنُهَا حَدِيقَةً مِنْ نَخْلٍ، فَمَاتَتْ، فَقَالَ ابْنُهَا: إِنَّمَا أَعْطَيْتُهَا حَيَاتَهَا، وَلَهُ إِخْوَةٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هِيَ لَهَا حَيَاتَهَا وَمَوْتَهَا". قَالَ: كُنْتُ تَصَدَّقْتُ بِهَا عَلَيْهَا، قَالَ: "ذَلِكَ أَبْعَدُ لَكَ". (د)', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ): ഒരു അൻസ്വാരീ സ്ത്രീക്ക് തന്റെ മകൻ ഒരു ഈത്തപ്പനത്തോട്ടം നൽകുകയും ശേഷം ആ സ്ത്രീ മരണപ്പെടുകയും ചെയ്തു. അപ്പോൾ മകൻ പറഞ്ഞു: അവരുടെ ജീവിതകാലത്തേക്കു മാത്രമായിട്ടാണ് ഞാൻ നൽകിയിരുന്നത്. അവന് വേറെ സഹോദരങ്ങളുമുണ്ട്. ഈ സ്ത്രീയുടെ വിഷയത്തിൽ റസൂൽ(സ) ഇപ്രകാരം വിധി പറഞ്ഞു: "അവളുടെ ജീവിത കാലത്തും മരണ ശേഷവും അത് അവൾക്കു തന്നെയുള്ളതാണ്." മകൻ പറഞ്ഞു: ഞാൻ അത് അവർക്ക് (മാത്രം) ദാനമായി നൽകിയതായിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അതു നീ ചെയ്യാൻ സാധ്യതയില്ലാത്തതാണ്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ലാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ طَاوُسٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَحِلُّ الرُّقْبَى، فَمَنْ أُرْقِبَ شَيْئًا فَهُوَ سَبِيلُ الْمِيرَاثِ". (ن)', 'ത്വാഊസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "റുഖ്ബാ ദാനം അനുവദനീയമല്ല. ആർക്കെങ്കിലും റുഖ്ബാ ദാനം നൽകപ്പെട്ടാൽ അത് അനന്തരമെടുക്കപ്പെടുന്ന മാർഗ്ഗമാണ് (അനന്തരമെടുക്കപ്പെടും)." (ന)', 'طَاوُسٍ قَالَ', 'ത്വാഊസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُرْقِبُوا أَمْوَالَكُمْ، فَمَنْ أُرْقِبَ شَيْئًا فَهُوَ لِمَنْ أُرْقِبَهُ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ മുതലിനെ നിങ്ങൾ റുഖ്ബാ ദാനമാക്കരുത്. ആരെങ്കിലും വല്ലതും റുഖ്ബാ ദാനമാക്കിയാൽ, ദാനമായി നൽകപ്പെട്ട വ്യക്തിക്കുള്ളതാണ് അത്." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْعُمْرَى جَائِزَةٌ لِمَنْ أَعْمَرَهَا، وَالرُّقْبَى جَائِزَةٌ لِمَنْ أَرْقَبَهَا، وَالْعَائِدُ فِي هِبَتِهِ كَالْعَائِدِ فِي قَيْئِهِ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഉംറാ ദാനം, അതു നൽകപ്പെട്ട വ്യക്തിക്ക് (നൽകിയവനു തിരിച്ചു ലഭിക്കാത്ത വിധം) നടപ്പാകുന്നതാണ്. റുഖ്ബാ ദാനം, അതു നൽകപ്പെട്ട വ്യക്തിക്ക് നടപ്പാകുന്നതാണ്. താൻ നൽകിയ ദാനത്തിലേക്ക് തിരിച്ചു പോകുന്നവൻ ഛർദ്ദിച്ചതിലേക്ക് തിരിച്ചു പോകുന്നവനെ പോലെയാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 877, 877, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: الْعُمْرَى وَالرُّقْبَى سَوَاءٌ. وَفِي رِوَايَةٍ قَالَ: لَا تَحِلُّ الرُّقْبَى وَلَا الْعُمْرَى، فَمَنْ أُعْمِرَ شَيْئًا فَهُوَ لَهُ، وَمَنْ أُرْقِبَ شَيْئًا فَهُوَ لَهُ. وَفِي رِوَايَةٍ قَالَ: لَا تَصْلُحُ الْعُمْرَى وَلَا الرُّقْبَى، فَمَنْ أُعْمِرَ شَيْئًا أَوْ أُرْقِبَ فَإِنَّهُ لِمَنْ أُعْمِرَهُ وَأُرْقِبَهُ حَيَاتَهُ وَمَوْتَهُ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഉംറാ ദാനവും റുഖ്ബാ ദാനവും സമമാണ്. മറ്റൊരു നിവേദനം: റുഖ്ബാ ദാനവും ഉംറാ ദാനവും അനുവദനീയമല്ല. ആർക്കെങ്കിലും വല്ലതും ഉംറാ ദാനമായി ലഭിച്ചാൽ അത് അവനുള്ളതാണ്. ,ആർക്കെങ്കിലും വല്ലതും റുഖ്ബാ ദാനമായി ലഭിച്ചാൽ അത് അവനുള്ളതാണ്. മറ്റൊരു നിവേദനം: ഉംറാ ദാനവും റുഖ്ബാ ദാനവും ശരിയാവുകയില്ല. ആരെങ്കിലും വല്ലതും ഉംറാ ദാനമായോ റുഖ്ബാ ദാനമായോ നൽകിയാൽ, നിശ്ചയം അത് തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും നൽകപ്പെട്ട വ്യക്തിക്കുള്ളതാണ്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ന']::text[], null, null, 877, 878, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=15 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=69), 1, 'وَفِي رِوَايَةٍ قَالَ: لَا تَحِلُّ الرُّقْبَى وَلَا الْعُمْرَى، فَمَنْ أُعْمِرَ شَيْئًا فَهُوَ لَهُ، وَمَنْ أُرْقِبَ شَيْئًا فَهُوَ لَهُ.', 'മറ്റൊരു നിവേദനം: റുഖ്ബാ ദാനവും ഉംറാ ദാനവും അനുവദനീയമല്ല. ആർക്കെങ്കിലും വല്ലതും ഉംറാ ദാനമായി ലഭിച്ചാൽ അത് അവനുള്ളതാണ്. ,ആർക്കെങ്കിലും വല്ലതും റുഖ്ബാ ദാനമായി ലഭിച്ചാൽ അത് അവനുള്ളതാണ്.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=15 and h.hadith_no=69), 2, 'وَفِي رِوَايَةٍ قَالَ: لَا تَصْلُحُ الْعُمْرَى وَلَا الرُّقْبَى، فَمَنْ أُعْمِرَ شَيْئًا أَوْ أُرْقِبَ فَإِنَّهُ لِمَنْ أُعْمِرَهُ وَأُرْقِبَهُ حَيَاتَهُ وَمَوْتَهُ. (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: ഉംറാ ദാനവും റുഖ്ബാ ദാനവും ശരിയാവുകയില്ല. ആരെങ്കിലും വല്ലതും ഉംറാ ദാനമായോ റുഖ്ബാ ദാനമായോ നൽകിയാൽ, നിശ്ചയം അത് തന്റെ ജീവിത കാലത്തും മരണ ശേഷവും നൽകപ്പെട്ട വ്യക്തിക്കുള്ളതാണ്. (ന)');
